window.QUIZ_DATA={"n01":[{"q":["A 1 Mbps link is shared by users who each need 100 kbps when active and are active 10% of the time. How many users can circuit switching support?","קו של 1 Mbps משותף למשתמשים שכל אחד צריך 100 kbps כשהוא פעיל, והם פעילים 10% מהזמן. כמה משתמשים circuit switching יכול לתמוך?"],"o":[["1","1"],["10","10"],["35","35"],["100","100"]],"a":1,"e":["Circuit switching reserves 100 kbps per user regardless of activity: 1 Mbps / 100 kbps = 10. Packet switching could support about 35 with a tiny overload probability.","Circuit switching שומר 100 kbps לכל משתמש בלי קשר לפעילות: ‏1 Mbps / 100 kbps = 10. ‏Packet switching יכול לתמוך בערך ב-35 עם הסתברות עומס זעירה."]},{"q":["A 1,500-byte packet crosses 3 links of 10 Mbps each with store-and-forward. Ignoring propagation, processing and queueing, the end-to-end delay is:","packet של 1,500 בתים עובר 3 קווים של 10 Mbps כל אחד ב-store-and-forward. בלי התפשטות, עיבוד ותורים, ההשהיה מקצה לקצה היא:"],"o":[["1.2 ms","1.2 ms"],["3.6 ms","3.6 ms"],["0.4 ms","0.4 ms"],["12 ms","12 ms"]],"a":1,"e":["L/R = 12,000 bits / 10<sup>7<\/sup> bps = 1.2 ms per link. Each router waits for the whole packet, so 3 × 1.2 = 3.6 ms.","L/R = 12,000 ביט / 10<sup>7<\/sup> = 1.2 ms לכל קו. כל נתב מחכה לכל ה-packet, ולכן 3 × 1.2 = 3.6 ms."]},{"q":["Which layers does a typical router implement?","אילו שכבות נתב טיפוסי מממש?"],"o":[["Application down to physical (all 5)","מאפליקציה עד פיזית (כל ה-5)"],["Network, link and physical","רשת, קו ופיזית"],["Link and physical only","רק קו ופיזית"],["Transport and network","תעבורה ורשת"]],"a":1,"e":["Routers forward by IP address, so they implement layers 1–3. Switches implement 1–2; hosts implement all 5.","נתבים מעבירים לפי כתובת IP, ולכן מממשים שכבות 1–3. ‏Switches מממשים 1–2; מחשבי קצה את כל ה-5."]},{"q":["Which access network has homes sharing the medium up to the provider's head end?","באיזו רשת גישה הבתים חולקים את התווך עד ה-head end של הספק?"],"o":[["DSL","DSL"],["Cable (HFC)","כבלים (HFC)"],["Enterprise switched Ethernet","Ethernet ארגוני עם switch"],["A dedicated leased line","קו חכור ייעודי"]],"a":1,"e":["In HFC many homes share the coax/fiber to the head end, so rates depend on neighbours. DSL gives each home its own line to the central office.","ב-HFC הרבה בתים חולקים את הקואקס/סיב עד ה-head end, ולכן הקצב תלוי בשכנים. ‏DSL נותן לכל בית קו משלו עד המרכזייה."]},{"q":["\"Forwarding\" in a router means:","\"Forwarding\" בנתב פירושו:"],"o":[["Computing the best paths with a routing algorithm","לחשב את המסלולים הטובים בעזרת אלגוריתם ניתוב"],["Moving an arriving packet to the right output link using the forwarding table","להעביר packet שהגיע לקו היציאה הנכון לפי טבלת ההעברה"],["Sending the packet back to the source","להחזיר את ה-packet למקור"],["Encrypting the packet","להצפין את ה-packet"]],"a":1,"e":["Forwarding is the local, per-packet action (nanoseconds, hardware). Routing is the global path computation that fills the tables.","Forwarding היא הפעולה המקומית על כל packet (ננו-שניות, חומרה). ‏Routing הוא החישוב הגלובלי של המסלולים שממלא את הטבלאות."]},{"q":["In TDM circuit switching with 24 slots on a 1.536 Mbps link, how long does a 640,000-bit file take once the circuit is up?","ב-TDM circuit switching עם 24 חריצים בקו של 1.536 Mbps, כמה זמן לוקח קובץ של 640,000 ביט אחרי שהמעגל הוקם?"],"o":[["0.42 s","0.42 s"],["10 s","10 s"],["24 s","24 s"],["1 s","1 s"]],"a":1,"e":["Each circuit gets 1.536 Mbps / 24 = 64 kbps. 640,000 / 64,000 = 10 s.","כל מעגל מקבל ‏1.536 Mbps / 24 = 64 kbps. ‏640,000 / 64,000 = 10 s."]},{"q":["Which two layers exist in OSI but not in the 5-layer Internet stack?","אילו שתי שכבות קיימות ב-OSI אבל לא במחסנית האינטרנט בת 5 השכבות?"],"o":[["Session and presentation","Session ו-Presentation"],["Transport and network","תעבורה ורשת"],["Link and physical","קו ופיזית"],["Routing and switching","ניתוב ומיתוג"]],"a":0,"e":["Presentation (format, encryption, compression) and session (synchronization, checkpointing). In the Internet stack the application does these if it needs them.","Presentation (ייצוג, הצפנה, דחיסה) ו-Session (סנכרון, נקודות ביקורת). במחסנית האינטרנט האפליקציה עושה את זה אם היא צריכה."]},{"q":["A host sends 5 packets of L bits back to back over 3 links of rate R (store-and-forward, no other delays). When does the last packet arrive?","מחשב שולח 5 חבילות של L ביט ברצף דרך 3 קווים בקצב R ‏(store-and-forward, בלי השהיות אחרות). מתי ה-packet האחרון מגיע?"],"o":[["15·L/R","15·L/R"],["7·L/R","7·L/R"],["5·L/R","5·L/R"],["3·L/R","3·L/R"]],"a":1,"e":["The pipeline fills: (N + P − 1)·L/R = (3 + 5 − 1)·L/R = 7·L/R. The links work in parallel on different packets.","הצינור מתמלא: ‏(N + P − 1)·L/R = (3 + 5 − 1)·L/R = 7·L/R. הקווים עובדים במקביל על חבילות שונות."]},{"q":["Tier-1 ISPs connect to each other mainly by:","ספקי tier-1 מתחברים זה לזה בעיקר באמצעות:"],"o":[["Buying transit from regional ISPs","קניית transit מספקים אזוריים"],["Settlement-free peering","Peering בלי תשלום"],["Circuit-switched telephone lines","קווי טלפון ב-circuit switching"],["Content provider networks","רשתות של ספקי תוכן"]],"a":1,"e":["Tier-1 networks are at the top of the hierarchy, so they have no provider to buy from; they peer with each other, usually without payment.","רשתות tier-1 בראש ההיררכיה, אין להן ממי לקנות; הן עושות peering אחת עם השנייה, בדרך כלל בלי תשלום."]}],"n02":[{"q":["A 1,000-byte packet on a 1 Mbps link 2,000 km long (s = 2·10<sup>8<\/sup> m/s). Which is larger?","חבילה של 1,000 בתים בקו של 1 Mbps באורך 2,000 ק\"מ (s = 2·10<sup>8<\/sup>). מה גדול יותר?"],"o":[["Transmission delay (8 ms) is smaller than propagation (10 ms)","השהיית השידור (8 ms) קטנה מההתפשטות (10 ms)"],["Transmission delay (8 ms) is larger than propagation (1 ms)","השהיית השידור (8 ms) גדולה מההתפשטות (1 ms)"],["They are equal","הן שוות"],["Transmission 80 ms, propagation 10 ms","שידור 80 ms, התפשטות 10 ms"]],"a":0,"e":["d<sub>trans<\/sub> = 8,000 / 10<sup>6<\/sup> = 8 ms. d<sub>prop<\/sub> = 2·10<sup>6<\/sup> / 2·10<sup>8<\/sup> = 10 ms.","d<sub>trans<\/sub> = 8,000 / 10<sup>6<\/sup> = 8 ms. ‏d<sub>prop<\/sub> = 2·10<sup>6<\/sup> / 2·10<sup>8<\/sup> = 10 ms."]},{"q":["Traffic intensity ρ = La/R approaches 1. What happens to the average queueing delay?","עוצמת התעבורה ρ = La/R מתקרבת ל-1. מה קורה להשהיית התור הממוצעת?"],"o":[["It stays constant","נשארת קבועה"],["It grows linearly","גדלה לינארית"],["It grows very large (towards infinity)","גדלה מאוד (לכיוון אינסוף)"],["It drops to zero","יורדת לאפס"]],"a":2,"e":["Queueing delay explodes as ρ → 1, and with ρ &gt; 1 more work arrives than can be served, so the delay is unbounded.","השהיית התור מתפוצצת כש-ρ ← 1, ועם ρ &gt; 1 מגיעה יותר עבודה ממה שאפשר לשרת, ולכן ההשהיה לא חסומה."]},{"q":["A server sends to a client through links of 10 Mbps, 2 Mbps and 100 Mbps. The end-to-end throughput is:","שרת שולח ללקוח דרך קווים של 10 Mbps, ‏2 Mbps ו-100 Mbps. התפוקה מקצה לקצה היא:"],"o":[["112 Mbps","112 Mbps"],["37.3 Mbps","37.3 Mbps"],["2 Mbps","2 Mbps"],["100 Mbps","100 Mbps"]],"a":2,"e":["Throughput is set by the bottleneck link: min(10, 2, 100) = 2 Mbps.","התפוקה נקבעת לפי צוואר הבקבוק: ‏min(10, 2, 100) = 2 Mbps."]},{"q":["What does traceroute measure in each line?","מה traceroute מודד בכל שורה?"],"o":[["The bandwidth of each link","רוחב הפס של כל קו"],["The round-trip time to each router on the path, using increasing TTL","זמן הלוך-חזור לכל נתב במסלול, עם TTL עולה"],["The one-way delay to the destination only","רק את ההשהיה החד-כיוונית ליעד"],["The number of packets dropped by each router","מספר החבילות שכל נתב זרק"]],"a":1,"e":["Traceroute sends 3 probes with TTL = 1, 2, 3…; router i drops the probe with TTL i and returns ICMP \"TTL exceeded\", and the sender times it.","traceroute שולח 3 גששים עם TTL = 1, 2, 3…; הנתב ה-i זורק את הגשש עם TTL i ומחזיר ICMP \"TTL exceeded\", והשולח מודד את הזמן."]},{"q":["Which delay component is typically a few microseconds and depends on the router hardware?","איזה רכיב השהיה הוא בדרך כלל כמה מיקרו-שניות ותלוי בחומרת הנתב?"],"o":[["Processing","עיבוד"],["Queueing","תור"],["Propagation","התפשטות"],["Transmission","שידור"]],"a":0,"e":["Nodal processing (check bit errors, look up the output link) is usually &lt; µs to a few µs.","עיבוד בצומת (בדיקת שגיאות, חיפוש קו יציאה) הוא בדרך כלל פחות ממיקרו-שנייה עד כמה מיקרו-שניות."]},{"q":["R = 100 Mbps, d<sub>prop<\/sub> = 20 ms. How many bits fit \"in flight\" on the link?","R = 100 Mbps, ‏d<sub>prop<\/sub> = 20 ms. כמה ביטים \"באוויר\" על הקו?"],"o":[["200,000","200,000"],["2,000,000","2,000,000"],["20,000,000","20,000,000"],["5,000","5,000"]],"a":1,"e":["BDP = R·d<sub>prop<\/sub> = 10<sup>8<\/sup> × 0.02 = 2·10<sup>6<\/sup> bits.","BDP = R·d<sub>prop<\/sub> = 10<sup>8<\/sup> × 0.02 = 2·10<sup>6<\/sup> ביט."]},{"q":["Why do we segment a large message into packets instead of sending it as one unit?","למה מחלקים הודעה גדולה לחבילות במקום לשלוח אותה כיחידה אחת?"],"o":[["It reduces the number of header bytes","זה מקטין את מספר בתי ה-header"],["Links can transmit different packets in parallel (pipelining), so the end-to-end delay drops","קווים יכולים לשדר חבילות שונות במקביל (pipelining), ולכן ההשהיה מקצה לקצה יורדת"],["It makes propagation faster","זה מאיץ את ההתפשטות"],["Routers cannot store more than one bit","נתבים לא יכולים לשמור יותר מביט אחד"]],"a":1,"e":["With one big message every router waits for all of it (N·M/R). With P packets the time is (N + P − 1)·L/R, much smaller. It also makes a bit error cost only one packet.","עם הודעה אחת גדולה כל נתב מחכה לכולה (N·M/R). עם P חבילות הזמן הוא (N + P − 1)·L/R, הרבה פחות. גם שגיאת ביט עולה רק חבילה אחת."]},{"q":["Packet loss in a router happens mainly because:","אובדן חבילות בנתב קורה בעיקר כי:"],"o":[["The link is too long","הקו ארוך מדי"],["The output buffer is full when the packet arrives","ה-buffer של היציאה מלא כשהחבילה מגיעה"],["The TTL is too large","ה-TTL גדול מדי"],["The checksum is always wrong","ה-checksum תמיד שגוי"]],"a":1,"e":["A queue has finite capacity; a packet arriving to a full queue is dropped, and may be retransmitted by the previous node, the source, or not at all.","לתור יש קיבולת סופית; חבילה שמגיעה לתור מלא נזרקת, ויכולה להישלח שוב ע\"י הצומת הקודם, המקור, או בכלל לא."]}],"n03":[{"q":["Base HTML + 10 small images, non-persistent HTTP with no parallel connections. Ignoring transmission times, the response time is:","HTML בסיס + 10 תמונות קטנות, ‏HTTP non-persistent בלי חיבורים מקבילים. בלי זמני שידור, זמן התגובה הוא:"],"o":[["2 RTT","2 RTT"],["11 RTT","11 RTT"],["12 RTT","12 RTT"],["22 RTT","22 RTT"]],"a":3,"e":["Each of the 11 objects needs 2 RTT (TCP setup + request/response): 11 × 2 = 22 RTT.","כל אחד מ-11 האובייקטים צריך 2 RTT ‏(הקמת TCP + בקשה/תשובה): ‏11 × 2 = 22 RTT."]},{"q":["HTTP is stateless. How does a web site remember a logged-in user?","HTTP הוא stateless. איך אתר זוכר משתמש מחובר?"],"o":[["By the client's IP address only","רק לפי כתובת ה-IP של הלקוח"],["With cookies: Set-Cookie in a response, Cookie in later requests, and a back-end database","עם cookies: ‏Set-Cookie בתשובה, Cookie בבקשות הבאות, ומסד נתונים בצד השרת"],["HTTP keeps a session in the TCP header","HTTP שומר session ב-header של TCP"],["With DNS","עם DNS"]],"a":1,"e":["The four components: a Set-Cookie header in the response, a Cookie header in requests, a cookie file in the browser, and a back-end database at the site.","ארבעת הרכיבים: header ‏Set-Cookie בתשובה, header ‏Cookie בבקשות, קובץ cookie בדפדפן, ומסד נתונים באתר."]},{"q":["A conditional GET receives \"304 Not Modified\". What happened?","GET מותנה מקבל \"304 Not Modified\". מה קרה?"],"o":[["The object was deleted","האובייקט נמחק"],["The cache's copy is up to date, so the server sent no object body","העותק ב-cache מעודכן, ולכן השרת לא שלח את גוף האובייקט"],["The server is down","השרת לא זמין"],["The request was malformed","הבקשה לא תקינה"]],"a":1,"e":["The cache sent If-Modified-Since: &lt;date&gt;; the server replies 304 without the object if it has not changed since that date.","ה-cache שלח If-Modified-Since: &lt;date&gt;; השרת עונה 304 בלי האובייקט אם הוא לא השתנה מאז התאריך הזה."]},{"q":["An institution's access link is 95% utilized. A cache with a 40% hit rate is installed. What happens?","קו הגישה של מוסד מנוצל ב-95%. מתקינים cache עם 40% פגיעות. מה קורה?"],"o":[["Access-link utilization drops to about 57%, and delay drops a lot","ניצול קו הגישה יורד לכ-57%, וההשהיה יורדת הרבה"],["Nothing changes","שום דבר לא משתנה"],["Utilization rises","הניצול עולה"],["Only the LAN delay changes","רק השהיית ה-LAN משתנה"]],"a":0,"e":["Only 60% of requests cross the link: 0.6 × 95% ≈ 57%. Away from ρ ≈ 1 the queueing delay becomes small. A cache is cheaper than a faster link.","רק 60% מהבקשות עוברות בקו: ‏0.6 × 95% ≈ 57%. רחוק מ-ρ ≈ 1 השהיית התור קטנה. ‏Cache זול יותר מקו מהיר יותר."]},{"q":["Which application-layer need does UDP NOT provide?","איזה צורך של האפליקציה UDP לא מספק?"],"o":[["Multiplexing by port","ריבוב לפי פורט"],["Reliable data transfer","העברת מידע אמינה"],["A checksum","Checksum"],["Low overhead","תקורה נמוכה"]],"a":1,"e":["UDP gives ports and a checksum only. Neither TCP nor UDP guarantee timing, throughput or security (TLS adds security on top of TCP).","UDP נותן רק פורטים ו-checksum. לא TCP ולא UDP מבטיחים תזמון, תפוקה או אבטחה (TLS מוסיף אבטחה מעל TCP)."]},{"q":["What problem of HTTP/1.1 does HTTP/2 mainly solve?","איזו בעיה של HTTP/1.1 ‏HTTP/2 פותר בעיקר?"],"o":[["Lack of encryption","חוסר הצפנה"],["Head-of-line blocking: a large object delays small objects behind it (FCFS)","Head-of-line blocking: אובייקט גדול מעכב אובייקטים קטנים שמאחוריו (FCFS)"],["DNS lookup time","זמן חיפוש DNS"],["Packet loss in TCP","אובדן חבילות ב-TCP"]],"a":1,"e":["HTTP/2 divides objects into frames and interleaves them, with client-specified priority. HTTP/3 (over QUIC/UDP) also removes TCP-level HOL blocking on loss.","HTTP/2 מחלק אובייקטים ל-frames ומשלב ביניהם, עם עדיפות שהלקוח קובע. ‏HTTP/3 ‏(מעל QUIC/UDP) גם מסיר HOL blocking ברמת TCP בזמן אובדן."]},{"q":["A process is identified on the Internet by:","תהליך מזוהה באינטרנט ע\"י:"],"o":[["Its IP address only","כתובת ה-IP בלבד"],["Its MAC address","כתובת ה-MAC"],["The host IP address plus a port number","כתובת ה-IP של המחשב ומספר פורט"],["The process ID (PID)","מזהה התהליך (PID)"]],"a":2,"e":["Many processes run on one host, so the identifier is IP + port (e.g. 128.119.245.12:80).","הרבה תהליכים רצים על מחשב אחד, ולכן המזהה הוא IP + פורט (למשל 128.119.245.12:80)."]},{"q":["Which status code means the resource has permanently moved?","איזה קוד סטטוס אומר שהמשאב עבר לצמיתות?"],"o":[["200","200"],["301","301"],["404","404"],["505","505"]],"a":1,"e":["301 Moved Permanently, with the new URL in the Location: header. 404 = not found, 505 = HTTP version not supported.","301 Moved Permanently, עם ה-URL החדש ב-header ‏Location:. ‏404 = לא נמצא, ‏505 = גרסת HTTP לא נתמכת."]}],"n04":[{"q":["Which protocol transfers mail between mail servers?","איזה פרוטוקול מעביר דואר בין שרתי דואר?"],"o":[["IMAP","IMAP"],["POP3","POP3"],["SMTP","SMTP"],["HTTP","HTTP"]],"a":2,"e":["SMTP (TCP port 25) is the push protocol between servers and from the user agent to its server. IMAP/POP3/HTTP are for retrieving mail.","SMTP ‏(TCP פורט 25) הוא פרוטוקול ה-push בין שרתים ומהמשתמש לשרת שלו. ‏IMAP/POP3/HTTP משמשים לשליפת דואר."]},{"q":["In an iterated DNS query, the local DNS server:","בשאילתת DNS איטרטיבית, שרת ה-DNS המקומי:"],"o":[["Sends one query and waits; the root does all the work","שולח שאילתה אחת ומחכה; ה-root עושה את כל העבודה"],["Queries root, then TLD, then authoritative, each replying \"I don't know, ask this server\"","שואל את ה-root, אחר כך את ה-TLD, אחר כך את ה-authoritative, וכל אחד עונה \"לא יודע, תשאל את השרת הזה\""],["Asks every server in parallel","שואל את כל השרתים במקביל"],["Never contacts the root","אף פעם לא פונה ל-root"]],"a":1,"e":["Iterated: contacted servers reply with the name of the next server. Recursive puts the burden on the contacted server (heavy load on upper levels).","איטרטיבי: השרתים עונים עם שם השרת הבא. רקורסיבי מטיל את העבודה על השרת שנשאל (עומס כבד על הרמות העליונות)."]},{"q":["Which DNS record type gives the mail server for a domain?","איזה סוג רשומת DNS נותן את שרת הדואר של דומיין?"],"o":[["A","A"],["NS","NS"],["CNAME","CNAME"],["MX","MX"]],"a":3,"e":["MX: name is the domain, value is the mail server name. A: hostname → IP. NS: domain → authoritative name server. CNAME: alias → canonical name.","MX: השם הוא הדומיין, הערך הוא שם שרת הדואר. ‏A: שם → IP. ‏NS: דומיין → שרת authoritative. ‏CNAME: כינוי → שם קנוני."]},{"q":["Why is DNS not centralized in one server?","למה DNS לא מרוכז בשרת אחד?"],"o":[["Single point of failure, traffic volume, distance to clients, maintenance: it does not scale","נקודת כשל יחידה, נפח תעבורה, מרחק מלקוחות, תחזוקה: זה לא מתרחב"],["DNS is too simple","DNS פשוט מדי"],["Because of NAT","בגלל NAT"],["It is centralized","הוא כן מרוכז"]],"a":0,"e":["A distributed hierarchical database (root, TLD, authoritative) with caching handles trillions of queries per day.","מסד נתונים היררכי מבוזר (root, ‏TLD, ‏authoritative) עם caching מטפל בטריליוני שאילתות ביום."]},{"q":["What is the difference between POP3 (download-and-delete) and IMAP?","מה ההבדל בין POP3 ‏(download-and-delete) לבין IMAP?"],"o":[["IMAP keeps messages on the server and syncs folders across devices","IMAP משאיר את ההודעות בשרת ומסנכרן תיקיות בין מכשירים"],["POP3 encrypts mail","POP3 מצפין דואר"],["IMAP sends mail between servers","IMAP שולח דואר בין שרתים"],["There is no difference","אין הבדל"]],"a":0,"e":["POP3 in download-and-delete mode leaves no copy for a second device. IMAP keeps state on the server.","POP3 במצב download-and-delete לא משאיר עותק למכשיר שני. ‏IMAP שומר מצב בשרת."]},{"q":["Which field links a DNS reply to the query that it answers?","איזה שדה מקשר תשובת DNS לשאילתה שהיא עונה עליה?"],"o":[["The 16-bit identification field","שדה ה-identification של 16 ביט"],["The TTL","ה-TTL"],["The flags","הדגלים"],["The number of answers","מספר התשובות"]],"a":0,"e":["Query and reply carry the same 16-bit ID. Guessing this ID (plus the port) is what DNS cache poisoning attacks try to do.","השאילתה והתשובה נושאות אותו ID של 16 ביט. לנחש את ה-ID הזה (ואת הפורט) זה מה שתקיפות DNS cache poisoning מנסות לעשות."]},{"q":["SMTP uses which transport and what kind of interaction?","SMTP משתמש באיזו תעבורה ובאיזה סוג אינטראקציה?"],"o":[["UDP, binary","UDP, בינארי"],["TCP port 25, command/response in 7-bit ASCII","TCP פורט 25, פקודה/תשובה ב-ASCII של 7 ביט"],["TCP port 80, stateless","TCP פורט 80, בלי מצב"],["UDP port 53","UDP פורט 53"]],"a":1,"e":["Commands such as HELO, MAIL FROM, RCPT TO, DATA, QUIT and replies with status codes; MIME encodes non-ASCII content.","פקודות כמו HELO, ‏MAIL FROM, ‏RCPT TO, ‏DATA, ‏QUIT ותשובות עם קודי סטטוס; MIME מקודד תוכן שאינו ASCII."]},{"q":["A new startup registers networkutopia.com. What records are put in the .com TLD servers?","סטארט-אפ חדש רושם את networkutopia.com. אילו רשומות נכנסות לשרתי ה-TLD של .com?"],"o":[["An NS record and an A record for its authoritative name server","רשומת NS ורשומת A לשרת ה-authoritative שלו"],["Only an MX record","רק רשומת MX"],["All its web pages","כל דפי האתר"],["Nothing","כלום"]],"a":0,"e":["(networkutopia.com, dns1.networkutopia.com, NS) and (dns1.networkutopia.com, 212.212.212.1, A). The company then adds its own A and MX records on its authoritative server.","(networkutopia.com, dns1.networkutopia.com, NS) ו-(dns1.networkutopia.com, 212.212.212.1, A). החברה מוסיפה אחר כך רשומות A ו-MX בשרת ה-authoritative שלה."]}],"n05":[{"q":["In client-server file distribution to N peers, the minimum distribution time grows:","בהפצת קובץ שרת-לקוח ל-N עמיתים, זמן ההפצה המינימלי גדל:"],"o":[["Logarithmically in N","לוגריתמית ב-N"],["Linearly in N (NF/u<sub>s<\/sub>)","לינארית ב-N ‏(NF/u<sub>s<\/sub>)"],["It does not depend on N","לא תלוי ב-N"],["Exponentially","מעריכית"]],"a":1,"e":["The server must upload N copies: NF/u<sub>s<\/sub>. In P2P each peer adds upload capacity, so the time grows much more slowly.","השרת חייב להעלות N עותקים: ‏NF/u<sub>s<\/sub>. ב-P2P כל עמית מוסיף קיבולת העלאה, ולכן הזמן גדל הרבה יותר לאט."]},{"q":["In BitTorrent, \"tit-for-tat\" means:","ב-BitTorrent, \"tit-for-tat\" פירושו:"],"o":[["A peer sends chunks to the 4 peers currently sending it chunks at the highest rate, plus one optimistically unchoked peer every 30 s","עמית שולח chunks ל-4 העמיתים ששולחים לו בקצב הגבוה ביותר, ועוד עמית אחד שנבחר אקראית כל 30 שניות"],["Every peer uploads to all others equally","כל עמית מעלה לכולם באופן שווה"],["The tracker sends the whole file","ה-tracker שולח את כל הקובץ"],["Peers download the rarest chunks last","עמיתים מורידים את ה-chunks הנדירים בסוף"]],"a":0,"e":["Top-4 unchoked every 10 s, plus optimistic unchoking. Requests go for the rarest chunks first.","4 המובילים ב-unchoke כל 10 שניות, ועוד optimistic unchoking. הבקשות הולכות קודם ל-chunks הנדירים."]},{"q":["In DASH, who decides which bitrate to request next?","ב-DASH, מי מחליט איזה bitrate לבקש בפעם הבאה?"],"o":[["The server","השרת"],["The client, using the manifest file and its measured bandwidth","הלקוח, לפי קובץ ה-manifest ורוחב הפס שהוא מודד"],["The CDN","ה-CDN"],["The DNS server","שרת ה-DNS"]],"a":1,"e":["\"Intelligence\" is at the client: it decides when to request a chunk, at what encoding rate, and from which URL (CDN node).","ה\"אינטליגנציה\" אצל הלקוח: הוא מחליט מתי לבקש chunk, באיזה קצב קידוד, ומאיזה URL (צומת CDN)."]},{"q":["Why does a video client buffer a few seconds before playout?","למה לקוח וידאו שומר כמה שניות ב-buffer לפני ההצגה?"],"o":[["To compensate for network-added delay variation (jitter)","כדי לפצות על השונות בהשהיה שהרשת מוסיפה (jitter)"],["To reduce bandwidth","כדי להקטין רוחב פס"],["To encrypt the video","כדי להצפין את הווידאו"],["Because UDP requires it","כי UDP מחייב את זה"]],"a":0,"e":["Chunks arrive with variable delay; a playout buffer lets constant-rate playout continue while arrivals fluctuate.","chunks מגיעים עם השהיה משתנה; buffer מאפשר הצגה בקצב קבוע בזמן שההגעות משתנות."]},{"q":["F = 1 Gbit, N = 10, u<sub>s<\/sub> = 50 Mbps, d<sub>min<\/sub> = 20 Mbps. Client-server distribution time?","F = 1 Gbit, ‏N = 10, ‏u<sub>s<\/sub> = 50 Mbps, ‏d<sub>min<\/sub> = 20 Mbps. זמן הפצה שרת-לקוח?"],"o":[["20 s","20 s"],["50 s","50 s"],["200 s","200 s"],["500 s","500 s"]],"a":2,"e":["max{NF/u<sub>s<\/sub>, F/d<sub>min<\/sub>} = max{10<sup>10<\/sup>/5·10<sup>7<\/sup>, 10<sup>9<\/sup>/2·10<sup>7<\/sup>} = max{200, 50} = 200 s.","max{NF/u<sub>s<\/sub>, F/d<sub>min<\/sub>} = max{10<sup>10<\/sup>/5·10<sup>7<\/sup>, 10<sup>9<\/sup>/2·10<sup>7<\/sup>} = max{200, 50} = 200 s."]},{"q":["In a UDP socket program, why must the client attach the server address to every message?","בתוכנית UDP socket, למה הלקוח חייב לצרף את כתובת השרת לכל הודעה?"],"o":[["Because UDP has no connection, so the socket is not bound to a peer","כי ל-UDP אין חיבור, ולכן ה-socket לא קשור לצד השני"],["For encryption","להצפנה"],["Because of NAT only","רק בגלל NAT"],["It doesn't have to","הוא לא חייב"]],"a":0,"e":["sendto(msg, (serverName, serverPort)). With TCP the client calls connect() once and then send().","sendto(msg, (serverName, serverPort)). ב-TCP הלקוח קורא ל-connect() פעם אחת ואז send()."]},{"q":["A TCP server calls accept(). What does it return?","שרת TCP קורא ל-accept(). מה זה מחזיר?"],"o":[["The same welcome socket","את אותו welcome socket"],["A new connection socket dedicated to that client","socket חיבור חדש שמוקדש ללקוח הזה"],["The client's MAC","את ה-MAC של הלקוח"],["Nothing, it only blocks","כלום, הוא רק חוסם"]],"a":1,"e":["The welcome (listening) socket keeps accepting new clients; each client gets its own socket, demultiplexed by the 4-tuple.","ה-welcome socket ממשיך לקבל לקוחות חדשים; כל לקוח מקבל socket משלו, שמזוהה לפי ה-4-tuple."]},{"q":["A CDN that places servers deep inside many access networks (close to users) follows which strategy?","CDN שמציב שרתים עמוק בתוך הרבה רשתות גישה (קרוב למשתמשים) פועל לפי איזו אסטרטגיה?"],"o":[["Enter deep (e.g. Akamai)","Enter deep (למשל Akamai)"],["Bring home (e.g. Limelight)","Bring home (למשל Limelight)"],["Central server","שרת מרכזי"],["Peer-to-peer","Peer-to-peer"]],"a":0,"e":["Enter deep: many small clusters close to users. Bring home: fewer, larger clusters at IXPs/POPs.","Enter deep: הרבה אשכולות קטנים קרוב למשתמשים. ‏Bring home: פחות אשכולות, גדולים יותר, ב-IXPs/POPs."]}],"n06":[{"q":["A UDP socket is identified by:","UDP socket מזוהה ע\"י:"],"o":[["Destination IP and destination port","IP יעד ופורט יעד"],["Source and destination IP and port (4-tuple)","IP ופורט של מקור ויעד (4-tuple)"],["MAC address","כתובת MAC"],["Source port only","רק פורט מקור"]],"a":0,"e":["UDP demux uses (dst IP, dst port) only: segments from different sources to the same port go to the same socket. TCP uses the 4-tuple.","demux של UDP משתמש רק ב-(IP יעד, פורט יעד): segments ממקורות שונים לאותו פורט מגיעים לאותו socket. ‏TCP משתמש ב-4-tuple."]},{"q":["Which mechanism did rdt 3.0 add over rdt 2.2?","איזה מנגנון rdt 3.0 הוסיף על rdt 2.2?"],"o":[["Sequence numbers","מספרי רצף"],["A countdown timer to recover from packet loss","טיימר כדי להתאושש מאובדן חבילות"],["A checksum","Checksum"],["NAKs","NAKs"]],"a":1,"e":["rdt 3.0 assumes the channel can also lose packets: the sender waits a \"reasonable\" time for an ACK and retransmits on timeout. Duplicates are handled by the sequence numbers already there.","rdt 3.0 מניח שהערוץ יכול גם לאבד חבילות: השולח מחכה זמן \"סביר\" ל-ACK ושולח שוב ב-timeout. כפילויות מטופלות במספרי הרצף שכבר קיימים."]},{"q":["R = 1 Gbps, L = 8,000 bits, RTT = 30 ms. Utilization of stop-and-wait?","R = 1 Gbps, ‏L = 8,000 ביט, ‏RTT = 30 ms. ניצולת stop-and-wait?"],"o":[["≈ 0.027%","≈ 0.027%"],["≈ 2.7%","≈ 2.7%"],["≈ 27%","≈ 27%"],["100%","100%"]],"a":0,"e":["U = (L/R)/(RTT + L/R) = 0.008/30.008 ≈ 0.00027. The protocol limits the physical resource.","U = (L/R)/(RTT + L/R) = 0.008/30.008 ≈ 0.00027. הפרוטוקול מגביל את המשאב הפיזי."]},{"q":["In Go-Back-N, the receiver gets packets 0, 1, 3 (2 was lost). What does it ACK when 3 arrives?","ב-Go-Back-N, המקבל מקבל חבילות 0, 1, 3 (2 אבדה). מה הוא שולח כ-ACK כש-3 מגיעה?"],"o":[["ACK 3","ACK 3"],["ACK 1 (duplicate), and it discards 3","ACK 1 (כפול), והוא זורק את 3"],["NAK 2","NAK 2"],["Nothing","כלום"]],"a":1,"e":["GBN uses cumulative ACKs and no out-of-order buffering: re-ACK the highest in-order packet (1). On timeout the sender resends 2 and everything after it.","GBN משתמש ב-ACK מצטבר ולא שומר חבילות שהגיעו לא לפי הסדר: שולחים שוב ACK לחבילה הגבוהה ביותר לפי הסדר (1). ב-timeout השולח שולח שוב את 2 וכל מה שאחריה."]},{"q":["With 3-bit sequence numbers, the maximum Selective Repeat window is:","עם מספרי רצף של 3 ביט, החלון המרבי של Selective Repeat הוא:"],"o":[["3","3"],["4","4"],["7","7"],["8","8"]],"a":1,"e":["SR needs window ≤ 2<sup>k<\/sup>/2 = 4, otherwise the receiver cannot tell new packets from retransmissions (the SR dilemma). GBN allows 2<sup>k<\/sup> − 1 = 7.","SR צריך חלון ≤ 2<sup>k<\/sup>/2 = 4, אחרת המקבל לא יכול להבדיל בין חבילות חדשות לשידורים חוזרים (הדילמה של SR). ‏GBN מאפשר 2<sup>k<\/sup> − 1 = 7."]},{"q":["Two 16-bit words are added for a checksum and the sum overflows. What does the sender do with the carry?","שתי מילים של 16 ביט מחוברות ל-checksum והסכום חורג. מה השולח עושה עם ה-carry?"],"o":[["Discards it","זורק אותו"],["Wraps it around and adds it to the lowest bit, then takes the one's complement","מחזיר אותו (wraparound) ומוסיף לביט הנמוך, ואז לוקח משלים ל-1"],["Puts it in the IP header","שם אותו ב-header של IP"],["Sends it as a separate segment","שולח אותו כ-segment נפרד"]],"a":1,"e":["One's complement sum with end-around carry, then invert all bits. The receiver adds everything including the checksum and expects all 1s.","סכום במשלים ל-1 עם carry שחוזר מסביב, ואז היפוך של כל הביטים. המקבל מחבר הכל כולל ה-checksum ומצפה לקבל רק 1."]},{"q":["Why does rdt 2.1 need sequence numbers?","למה rdt 2.1 צריך מספרי רצף?"],"o":[["To detect lost packets","כדי לזהות חבילות שאבדו"],["Because ACK/NAK can be corrupted; the sender retransmits, and the receiver must recognize duplicates","כי ACK/NAK יכולים להשתבש; השולח שולח שוב, והמקבל חייב לזהות כפילויות"],["For congestion control","לבקרת עומס"],["To encrypt packets","כדי להצפין חבילות"]],"a":1,"e":["A garbled ACK/NAK makes the sender retransmit, possibly a duplicate; a 1-bit sequence number (0/1) lets the receiver discard it.","ACK/NAK משובש גורם לשולח לשלוח שוב, אולי כפילות; מספר רצף של ביט אחד (0/1) מאפשר למקבל לזרוק אותה."]},{"q":["The UDP header is:","ה-header של UDP הוא:"],"o":[["8 bytes: source port, destination port, length, checksum","8 בתים: פורט מקור, פורט יעד, אורך, checksum"],["20 bytes","20 בתים"],["4 bytes: ports only","4 בתים: רק פורטים"],["Variable, with options","משתנה, עם אופציות"]],"a":0,"e":["Four 16-bit fields. Small header, no connection state, no congestion control: why DNS, SNMP, HTTP/3 (QUIC) and streaming use it.","ארבעה שדות של 16 ביט. header קטן, בלי מצב חיבור, בלי בקרת עומס: לכן DNS, ‏SNMP, ‏HTTP/3 ‏(QUIC) ו-streaming משתמשים בו."]}],"n07":[{"q":["Host A sends a segment with seq = 92 and 8 bytes of data. What ACK number does B send if it received it correctly and in order?","מחשב A שולח segment עם seq = 92 ו-8 בתים של מידע. איזה מספר ACK ‏B שולח אם קיבל אותו תקין ולפי הסדר?"],"o":[["92","92"],["93","93"],["100","100"],["8","8"]],"a":2,"e":["TCP ACKs are cumulative and name the next expected byte: 92 + 8 = 100.","ACK של TCP מצטבר ומציין את הבית הבא שמצופה: ‏92 + 8 = 100."]},{"q":["After receiving 3 duplicate ACKs, TCP Reno:","אחרי 3 ACKים כפולים, TCP Reno:"],"o":[["Sets cwnd = 1 MSS and enters slow start","קובע cwnd = 1 MSS ונכנס ל-slow start"],["Fast retransmits, halves cwnd (ssthresh = cwnd/2, cwnd = ssthresh + 3) and continues","שולח מיד (fast retransmit), מחצה את cwnd ‏(ssthresh = cwnd/2, ‏cwnd = ssthresh + 3) וממשיך"],["Closes the connection","סוגר את החיבור"],["Ignores them","מתעלם מהם"]],"a":1,"e":["3 dup ACKs mean later segments are getting through, so congestion is mild: multiplicative decrease. Timeout is worse: cwnd = 1 MSS (TCP Tahoe does this for both).","3 ACKים כפולים אומרים שסגמנטים מאוחרים יותר עוברים, ולכן העומס קל: הקטנה כפלית. ‏Timeout גרוע יותר: ‏cwnd = 1 MSS ‏(TCP Tahoe עושה את זה בשני המקרים)."]},{"q":["In slow start, cwnd:","ב-slow start, ‏cwnd:"],"o":[["Grows by 1 MSS per RTT","גדל ב-1 MSS בכל RTT"],["Doubles every RTT (+1 MSS per ACK)","מוכפל כל RTT (+1 MSS לכל ACK)"],["Stays constant","נשאר קבוע"],["Halves every RTT","מתחצה כל RTT"]],"a":1,"e":["Exponential growth until ssthresh, then congestion avoidance: +1 MSS per RTT (linear).","גדילה מעריכית עד ssthresh, ואז congestion avoidance: ‏+1 MSS לכל RTT (לינארי)."]},{"q":["What does the receive window (rwnd) field prevent?","מה שדה ה-receive window ‏(rwnd) מונע?"],"o":[["Network congestion","עומס ברשת"],["The sender overflowing the receiver's buffer (flow control)","שהשולח יציף את ה-buffer של המקבל (בקרת זרימה)"],["Packet corruption","שיבוש חבילות"],["IP fragmentation","פיצול IP"]],"a":1,"e":["rwnd = free buffer space advertised by the receiver; the sender keeps unACKed data ≤ min(rwnd, cwnd).","rwnd = המקום הפנוי ב-buffer שהמקבל מפרסם; השולח שומר מידע שלא אושר ≤ min(rwnd, cwnd)."]},{"q":["EstimatedRTT = 100 ms, SampleRTT = 140 ms, α = 0.125. New EstimatedRTT?","EstimatedRTT = 100 ms, ‏SampleRTT = 140 ms, ‏α = 0.125. מה ה-EstimatedRTT החדש?"],"o":[["105 ms","105 ms"],["120 ms","120 ms"],["140 ms","140 ms"],["102.5 ms","102.5 ms"]],"a":0,"e":["0.875 × 100 + 0.125 × 140 = 87.5 + 17.5 = 105 ms.","0.875 × 100 + 0.125 × 140 = 87.5 + 17.5 = 105 ms."]},{"q":["Why does TCP use a 3-way handshake instead of 2-way?","למה TCP משתמש בלחיצת יד משולשת ולא כפולה?"],"o":[["To exchange encryption keys","כדי להחליף מפתחות הצפנה"],["So both sides agree on initial sequence numbers and old duplicate SYNs cannot create half-open connections","כדי ששני הצדדים יסכימו על מספרי הרצף ההתחלתיים, ו-SYNים ישנים כפולים לא ייצרו חיבורים חצי-פתוחים"],["To measure bandwidth","כדי למדוד רוחב פס"],["It uses 2-way","הוא משתמש בכפולה"]],"a":1,"e":["With 2-way handshakes, delayed retransmitted connection requests or data can be accepted after the client is gone. SYN, SYNACK, ACK confirms both ISNs.","בלחיצה כפולה, בקשות חיבור או מידע ישנים שהתעכבו יכולים להתקבל אחרי שהלקוח כבר הלך. ‏SYN, ‏SYNACK, ‏ACK מאשרים את שני ה-ISNs."]},{"q":["Two TCP flows share a bottleneck of rate R. Under AIMD, they converge to:","שני זרמי TCP חולקים צוואר בקבוק בקצב R. תחת AIMD, הם מתכנסים ל:"],"o":[["One flow gets everything","זרם אחד מקבל הכל"],["An equal share, R/2 each","חלוקה שווה, R/2 לכל אחד"],["Random shares","חלוקה אקראית"],["Zero throughput","תפוקה אפס"]],"a":1,"e":["Additive increase moves along a 45° line, multiplicative decrease halves both and moves toward the equal-share line, so they converge to fairness (same RTT, CA phase).","הגדלה חיבורית נעה בקו של 45°, הקטנה כפלית מחצה את שניהם ומתקרבת לקו החלוקה השווה, ולכן הם מתכנסים להוגנות (אותו RTT, שלב CA)."]},{"q":["Which TCP header flag is used to start a connection?","איזה דגל ב-header של TCP משמש לפתיחת חיבור?"],"o":[["FIN","FIN"],["RST","RST"],["SYN","SYN"],["PSH","PSH"]],"a":2,"e":["SYN starts, FIN closes gracefully, RST aborts. The SYN flood and RST injection attacks in the security course abuse exactly these.","SYN פותח, FIN סוגר בצורה מסודרת, RST מבטל. תקיפות SYN flood ו-RST injection בקורס האבטחה מנצלות בדיוק את אלה."]}],"n08":[{"q":["Which address in 200.23.16.0/20 is the broadcast address?","איזו כתובת ב-200.23.16.0/20 היא כתובת ה-broadcast?"],"o":[["200.23.16.255","200.23.16.255"],["200.23.31.255","200.23.31.255"],["200.23.255.255","200.23.255.255"],["200.23.17.255","200.23.17.255"]],"a":1,"e":["/20 leaves 12 host bits: the third octet spans 16–31. All host bits set → 200.23.31.255.","/20 משאיר 12 ביטים למחשבים: האוקטט השלישי מכסה 16–31. כל ביטי המחשב דלוקים ← 200.23.31.255."]},{"q":["A forwarding table has 11001000 00010111 00010*** and 11001000 00010111 00011000 *. Destination 11001000 00010111 00011000 10101010 goes to:","בטבלת העברה יש 11001000 00010111 00010*** ו-11001000 00010111 00011000 *. היעד 11001000 00010111 00011000 10101010 הולך ל:"],"o":[["The first entry","הרשומה הראשונה"],["The second entry (longest prefix match)","הרשומה השנייה (longest prefix match)"],["Both","לשתיהן"],["The default route","ל-default route"]],"a":1,"e":["The destination does not match 00010*** (third byte is 00011000). It matches the 24-bit prefix, which is longest.","היעד לא מתאים ל-00010*** (הבית השלישי הוא 00011000). הוא מתאים לקידומת של 24 ביט, שהיא הארוכה ביותר."]},{"q":["DHCP's four messages, in order, are:","ארבע הודעות DHCP, לפי הסדר, הן:"],"o":[["Request, Offer, Discover, ACK","Request, ‏Offer, ‏Discover, ‏ACK"],["Discover, Offer, Request, ACK","Discover, ‏Offer, ‏Request, ‏ACK"],["Offer, Discover, ACK, Request","Offer, ‏Discover, ‏ACK, ‏Request"],["Discover, ACK, Offer, Request","Discover, ‏ACK, ‏Offer, ‏Request"]],"a":1,"e":["DORA. Discover and Request are broadcast (the client has no address yet), over UDP ports 67/68.","DORA. ‏Discover ו-Request ב-broadcast (ללקוח עוד אין כתובת), מעל UDP פורטים 67/68."]},{"q":["A 2,000-byte datagram (20-byte header) crosses a link with MTU 1,000. How many fragments, and what is the second fragment's offset?","Datagram של 2,000 בתים (header של 20) עובר קו עם MTU 1,000. כמה fragments, ומה ה-offset של השני?"],"o":[["2 fragments, offset 1,000","2 fragments, ‏offset 1,000"],["3 fragments, offset 122","3 fragments, ‏offset 122"],["3 fragments, offset 976","3 fragments, ‏offset 976"],["2 fragments, offset 122","2 fragments, ‏offset 122"]],"a":1,"e":["Data = 1,980; per fragment ⌊980/8⌋·8 = 976 → 976 + 976 + 28 = 3 fragments. Second offset = 976/8 = 122.","מידע = 1,980; לכל fragment ‏⌊980/8⌋·8 = 976 ← 976 + 976 + 28 = 3 fragments. ה-offset של השני = 976/8 = 122."]},{"q":["NAT lets a home network use one public IP. It identifies each internal connection by:","NAT מאפשר לרשת ביתית להשתמש ב-IP ציבורי אחד. הוא מזהה כל חיבור פנימי לפי:"],"o":[["MAC address","כתובת MAC"],["A translation table mapping (public IP, new port) ↔ (private IP, port)","טבלת תרגום שממפה (IP ציבורי, פורט חדש) ↔ (IP פרטי, פורט)"],["The TTL","ה-TTL"],["DNS names","שמות DNS"]],"a":1,"e":["NAT rewrites the source IP and port on the way out and reverses it on the way in. 16-bit ports allow ~60,000 simultaneous connections.","NAT משכתב את ה-IP והפורט של המקור ביציאה, והופך את זה בכניסה. פורטים של 16 ביט מאפשרים ~60,000 חיבורים בו-זמניים."]},{"q":["Which IPv4 field does IPv6 remove from the base header?","איזה שדה של IPv4 ‏IPv6 מוציא מה-header הבסיסי?"],"o":[["Source address","כתובת מקור"],["Header checksum (and fragmentation fields)","Checksum של ה-header (ושדות הפיצול)"],["Hop limit","Hop limit"],["Version","Version"]],"a":1,"e":["IPv6 has a fixed 40-byte header, no checksum (faster per-hop processing), no fragmentation at routers (ICMPv6 \"packet too big\"), and a flow label.","ל-IPv6 header קבוע של 40 בתים, בלי checksum (עיבוד מהיר יותר בכל קפיצה), בלי פיצול בנתבים (ICMPv6 \"packet too big\"), ועם flow label."]},{"q":["Head-of-line (HOL) blocking in a router happens at:","Head-of-line ‏(HOL) blocking בנתב קורה ב:"],"o":[["Output ports, when the link is slow","פורטי היציאה, כשהקו איטי"],["Input ports, when a queued datagram at the front blocks others behind it from moving forward","פורטי הכניסה, כש-datagram בראש התור חוסם את מי שמאחוריו מלהתקדם"],["The routing processor","מעבד הניתוב"],["DNS","DNS"]],"a":1,"e":["If the switch fabric is slower than the input ports combined, input queues form; the packet at the head may wait for a busy output while the packet behind it could have gone.","אם ה-switch fabric איטי מסכום פורטי הכניסה, נוצרים תורים בכניסה; החבילה בראש התור מחכה ליציאה תפוסה בזמן שזו שמאחוריה הייתה יכולה לעבור."]},{"q":["In SDN / generalized forwarding, a flow-table entry is:","ב-SDN / העברה מוכללת, רשומה בטבלת זרימה היא:"],"o":[["Destination IP → output port only","רק IP יעד ← פורט יציאה"],["Match on many header fields (L2–L4) + action (forward, drop, modify, send to controller) + priority + counters","Match על הרבה שדות header ‏(L2–L4) + action (העברה, זריקה, שינוי, שליחה לבקר) + עדיפות + מונים"],["A BGP route","נתיב BGP"],["An ARP entry","רשומת ARP"]],"a":1,"e":["OpenFlow's match+action unifies routers (match dst IP), switches (match dst MAC), firewalls (match ports, drop) and NAT (rewrite).","match+action של OpenFlow מאחד נתבים (match לפי IP יעד), ‏switches (לפי MAC יעד), ‏firewalls (לפי פורטים, drop) ו-NAT (שכתוב)."]}],"n09":[{"q":["Dijkstra's algorithm requires each node to know:","האלגוריתם של Dijkstra דורש שכל צומת יידע:"],"o":[["Only its neighbors' distance vectors","רק את ה-distance vectors של השכנים"],["The full network topology and all link costs (link-state broadcast)","את כל הטופולוגיה ואת כל עלויות הקווים (link-state broadcast)"],["Only its own link costs","רק את עלויות הקווים שלו"],["Nothing","כלום"]],"a":1,"e":["Link-state: every node floods its link costs, so all nodes have the same map and compute shortest paths locally.","Link-state: כל צומת מציף את עלויות הקווים שלו, ולכן לכל הצמתים אותה מפה, וכל אחד מחשב מסלולים קצרים מקומית."]},{"q":["In distance vector routing, \"count to infinity\" happens when:","ב-distance vector, ‏\"count to infinity\" קורה כש:"],"o":[["A link cost decreases","עלות קו יורדת"],["A link cost increases a lot, and neighbors keep routing through each other with stale info","עלות קו עולה הרבה, ושכנים ממשיכים לנתב דרך זה דרך זה עם מידע ישן"],["There are too many nodes","יש יותר מדי צמתים"],["Dijkstra is used","משתמשים ב-Dijkstra"]],"a":1,"e":["\"Good news travels fast, bad news travels slow.\" Poisoned reverse (advertise ∞ back to the next hop) fixes 2-node loops but not longer ones.","\"חדשות טובות מגיעות מהר, חדשות רעות לאט.\" ‏Poisoned reverse (לפרסם ∞ חזרה לקפיצה הבאה) פותר לולאות של 2 צמתים אבל לא ארוכות יותר."]},{"q":["x has neighbors v (c = 2) and w (c = 5). d<sub>v<\/sub>(z) = 3, d<sub>w<\/sub>(z) = 1. Then d<sub>x<\/sub>(z) =","ל-x שכנים v ‏(c = 2) ו-w ‏(c = 5). ‏d<sub>v<\/sub>(z) = 3, ‏d<sub>w<\/sub>(z) = 1. אז d<sub>x<\/sub>(z) ="],"o":[["4","4"],["5","5"],["6","6"],["1","1"]],"a":1,"e":["Bellman-Ford: min{2 + 3, 5 + 1} = min{5, 6} = 5, via v.","Bellman-Ford: ‏min{2 + 3, 5 + 1} = min{5, 6} = 5, דרך v."]},{"q":["What does BGP's AS-PATH attribute let a router do?","מה תכונת AS-PATH של BGP מאפשרת לנתב לעשות?"],"o":[["Compute shortest delay","לחשב השהיה קצרה ביותר"],["Detect loops and apply policy (prefer shorter AS paths, avoid certain ASes)","לזהות לולאות ולהפעיל מדיניות (להעדיף מסלולי AS קצרים, להימנע מ-ASes מסוימים)"],["Encrypt routes","להצפין נתיבים"],["Assign IP addresses","להקצות כתובות IP"]],"a":1,"e":["AS-PATH lists the ASes a prefix advertisement passed through. NEXT-HOP gives the IP of the router interface that begins the AS-PATH.","AS-PATH מונה את ה-ASes שהפרסום של הקידומת עבר דרכם. ‏NEXT-HOP נותן את ה-IP של ממשק הנתב שמתחיל את ה-AS-PATH."]},{"q":["Why are intra-AS and inter-AS routing different?","למה ניתוב בתוך AS ובין ASes שונים?"],"o":[["Intra-AS focuses on performance; inter-AS is about policy and scale","בתוך AS מתמקדים בביצועים; בין ASes מדובר במדיניות ובהיקף"],["They are the same","הם אותו דבר"],["Inter-AS is always faster","בין ASes תמיד מהיר יותר"],["Intra-AS uses BGP","בתוך AS משתמשים ב-BGP"]],"a":0,"e":["An admin controls one AS, so performance rules; between ASes, who carries whose traffic is a business decision. Hierarchical routing also shrinks tables.","מנהל אחד שולט ב-AS, ולכן הביצועים קובעים; בין ASes, מי מעביר את התעבורה של מי היא החלטה עסקית. ניתוב היררכי גם מקטין טבלאות."]},{"q":["Traceroute stops when it receives:","traceroute מפסיק כשהוא מקבל:"],"o":[["ICMP echo request","ICMP echo request"],["ICMP \"port unreachable\" (type 3 code 3) from the destination","ICMP \"port unreachable\" ‏(type 3 code 3) מהיעד"],["A TCP RST","TCP RST"],["A DNS reply","תשובת DNS"]],"a":1,"e":["The UDP probe goes to an unlikely port; routers along the way reply type 11 (TTL expired), and the destination replies \"port unreachable\".","גשש ה-UDP נשלח לפורט לא סביר; נתבים בדרך עונים type 11 ‏(TTL expired), והיעד עונה \"port unreachable\"."]},{"q":["OSPF is:","OSPF הוא:"],"o":[["A distance vector protocol using hop count","פרוטוקול distance vector לפי מספר קפיצות"],["A link-state protocol that floods link-state advertisements and runs Dijkstra; supports hierarchy (areas) and authentication","פרוטוקול link-state שמציף הודעות link-state ומריץ Dijkstra; תומך בהיררכיה (areas) ובאימות"],["The inter-AS protocol","הפרוטוקול בין ASes"],["A transport protocol","פרוטוקול תעבורה"]],"a":1,"e":["OSPF messages go directly over IP. Two-level hierarchy: local areas and a backbone. RIP is the classic distance-vector example.","הודעות OSPF עוברות ישירות מעל IP. היררכיה של שתי רמות: areas מקומיים ו-backbone. ‏RIP הוא הדוגמה הקלאסית ל-distance vector."]},{"q":["In \"hot potato\" routing, a router chooses the gateway:","בניתוב \"hot potato\", נתב בוחר את ה-gateway:"],"o":[["With the shortest AS-PATH","עם ה-AS-PATH הקצר ביותר"],["With the least intra-domain cost, regardless of the inter-domain cost","עם העלות הפנימית הנמוכה ביותר, בלי קשר לעלות החיצונית"],["At random","באקראי"],["Chosen by DNS","שנבחר ע\"י DNS"]],"a":1,"e":["Get the packet out of your own AS as quickly (cheaply) as possible. It is one of the BGP route-selection tie-breakers.","להוציא את החבילה מה-AS שלך מהר (בזול) ככל האפשר. זה אחד ממשברי השוויון בבחירת נתיב ב-BGP."]}],"n10":[{"q":["D = 101110, G = 1001. The CRC bits R are:","D = 101110, ‏G = 1001. ביטי ה-CRC ‏R הם:"],"o":[["011","011"],["101","101"],["000","000"],["110","110"]],"a":0,"e":["Append 3 zeros and divide 101110000 by 1001 with XOR: the remainder is 011.","מוסיפים 3 אפסים ומחלקים את 101110000 ב-1001 עם XOR: השארית 011."]},{"q":["Maximum efficiency of slotted ALOHA with many nodes:","היעילות המרבית של slotted ALOHA עם הרבה צמתים:"],"o":[["1/(2e) ≈ 0.18","1/(2e) ≈ 0.18"],["1/e ≈ 0.37","1/e ≈ 0.37"],["0.5","0.5"],["1","1"]],"a":1,"e":["Np(1−p)<sup>N−1<\/sup> maximized at p = 1/N tends to 1/e. Pure ALOHA has twice the vulnerable period: 1/(2e).","Np(1−p)<sup>N−1<\/sup> במקסימום ב-p = 1/N שואף ל-1/e. ל-ALOHA טהור תקופה פגיעה כפולה: ‏1/(2e)."]},{"q":["After its 4th collision, an Ethernet NIC chooses K from:","אחרי ההתנגשות הרביעית, כרטיס Ethernet בוחר K מ:"],"o":[["{0, 1, 2, 3}","{0, 1, 2, 3}"],["{0, …, 15}","{0, …, 15}"],["{0, …, 4}","{0, …, 4}"],["{1, …, 16}","{1, …, 16}"]],"a":1,"e":["Binary exponential backoff: K ∈ {0, …, 2<sup>m<\/sup> − 1} = {0, …, 15}; it waits K·512 bit times.","Binary exponential backoff: ‏K ∈ {0, …, 2<sup>m<\/sup> − 1} = {0, …, 15}; מחכים K·512 זמני ביט."]},{"q":["A host wants to send to an IP on a different subnet. It sends an ARP request for:","מחשב רוצה לשלוח ל-IP ב-subnet אחרת. הוא שולח ARP request עבור:"],"o":[["The destination's IP","ה-IP של היעד"],["Its default gateway's IP","ה-IP של ה-default gateway שלו"],["The DNS server","שרת ה-DNS"],["No ARP is needed","לא צריך ARP"]],"a":1,"e":["ARP works only inside the subnet. The frame goes to the router's MAC; the IP destination stays the remote host.","ARP עובד רק בתוך ה-subnet. ה-frame נשלח ל-MAC של הנתב; ה-IP של היעד נשאר המחשב המרוחק."]},{"q":["A switch receives a frame for a destination MAC that is not in its table. It:","Switch מקבל frame ל-MAC יעד שלא בטבלה שלו. הוא:"],"o":[["Drops it","זורק אותו"],["Floods it on all ports except the incoming one","מציף אותו בכל הפורטים חוץ מזה שממנו הגיע"],["Sends it to the router","שולח אותו לנתב"],["Sends an ARP request","שולח ARP request"]],"a":1,"e":["And it learns the source MAC ↔ incoming port. When the reply comes back, the destination is learned too.","והוא לומד את ה-MAC של המקור ↔ הפורט הנכנס. כשהתשובה חוזרת, גם היעד נלמד."]},{"q":["Two-dimensional parity can:","Parity דו-ממדי יכול:"],"o":[["Only detect single-bit errors","רק לזהות שגיאות של ביט אחד"],["Detect and correct single-bit errors","לזהות ולתקן שגיאות של ביט אחד"],["Correct any number of errors","לתקן כל מספר שגיאות"],["Not detect anything","לא לזהות כלום"]],"a":1,"e":["The flipped bit is at the intersection of the failing row and column, so it can be flipped back.","הביט שהתהפך נמצא בחיתוך של השורה והעמודה שנכשלו, ולכן אפשר להפוך אותו חזרה."]},{"q":["Why does Ethernet have a minimum frame size (64 bytes)?","למה ל-Ethernet יש גודל frame מינימלי (64 בתים)?"],"o":[["To save bandwidth","כדי לחסוך רוחב פס"],["So a sender is still transmitting when a collision from the far end returns (t<sub>trans<\/sub> ≥ 2·t<sub>prop<\/sub>)","כדי שהשולח עדיין ישדר כשהתנגשות מהקצה הרחוק חוזרת (t<sub>trans<\/sub> ≥ 2·t<sub>prop<\/sub>)"],["For the CRC only","רק בשביל ה-CRC"],["Because of IP","בגלל IP"]],"a":1,"e":["If a frame ends before the collision signal arrives, the sender would think it succeeded. 512 bits is also the backoff slot.","אם ה-frame נגמר לפני שאות ההתנגשות מגיע, השולח יחשוב שהצליח. ‏512 ביט הם גם חריץ ה-backoff."]},{"q":["What does the 802.1Q tag add to a frame on a trunk link?","מה ה-tag של 802.1Q מוסיף ל-frame ב-trunk?"],"o":[["A 12-bit VLAN ID and 3-bit priority (4 bytes total)","מזהה VLAN של 12 ביט ועדיפות של 3 ביט (4 בתים בסך הכל)"],["An IP address","כתובת IP"],["A second MAC address","כתובת MAC שנייה"],["Encryption","הצפנה"]],"a":0,"e":["TPID 0x8100 + priority + CFI + VLAN ID; the CRC is recomputed. Up to 4,094 VLANs.","TPID 0x8100 + עדיפות + CFI + מזהה VLAN; ה-CRC מחושב מחדש. עד 4,094 VLANs."]}],"n11":[{"q":["In the \"day in the life\" sequence, which happens first when a laptop joins a network?","ברצף \"יום בחיים\", מה קורה ראשון כשמחשב נייד מצטרף לרשת?"],"o":[["DNS","DNS"],["ARP","ARP"],["DHCP","DHCP"],["TCP SYN","TCP SYN"]],"a":2,"e":["DHCP gives the IP, gateway and DNS server; then ARP for the gateway, DNS for the name, TCP handshake, HTTP.","DHCP נותן IP, ‏gateway ושרת DNS; אחר כך ARP ל-gateway, ‏DNS לשם, לחיצת יד TCP, ‏HTTP."]},{"q":["A 1,500-byte packet over 3 links of 2 Mbps, each with 5 ms propagation, 2 routers with 1 ms processing, no queueing. Total delay?","חבילה של 1,500 בתים על 3 קווים של 2 Mbps, לכל אחד 5 ms התפשטות, 2 נתבים עם 1 ms עיבוד, בלי תור. השהיה כוללת?"],"o":[["21 ms","21 ms"],["33 ms","33 ms"],["35 ms","35 ms"],["18 ms","18 ms"]],"a":2,"e":["3 × 6 ms transmission + 3 × 5 ms propagation + 2 × 1 ms processing = 35 ms.","3 × 6 ms שידור + 3 × 5 ms התפשטות + 2 × 1 ms עיבוד = 35 ms."]},{"q":["Which pair is about protecting the network rather than the receiver?","איזה מנגנון מגן על הרשת ולא על המקבל?"],"o":[["rwnd","rwnd"],["cwnd (congestion control)","cwnd (בקרת עומס)"],["checksum","checksum"],["sequence numbers","מספרי רצף"]],"a":1,"e":["Flow control (rwnd) protects the receiver's buffer; congestion control (cwnd) protects the routers in between.","בקרת זרימה (rwnd) מגינה על ה-buffer של המקבל; בקרת עומס (cwnd) מגינה על הנתבים בדרך."]},{"q":["Usable hosts in 10.0.0.0/22?","כמה מחשבים שמישים ב-10.0.0.0/22?"],"o":[["254","254"],["510","510"],["1,022","1,022"],["1,024","1,024"]],"a":2,"e":["2<sup>10<\/sup> − 2 = 1,022 (network and broadcast addresses reserved).","2<sup>10<\/sup> − 2 = 1,022 (כתובת הרשת וה-broadcast שמורות)."]},{"q":["A switch and a router both:","Switch ונתב שניהם:"],"o":[["Use IP addresses","משתמשים בכתובות IP"],["Are store-and-forward devices with forwarding tables","הם רכיבי store-and-forward עם טבלאות העברה"],["Run Dijkstra","מריצים Dijkstra"],["Need manual configuration of every host","צריכים הגדרה ידנית של כל מחשב"]],"a":1,"e":["Switch: layer 2, learns by flooding. Router: layer 3, tables computed by routing algorithms.","Switch: שכבה 2, לומד מהצפה. נתב: שכבה 3, הטבלאות מחושבות ע\"י אלגוריתמי ניתוב."]},{"q":["Non-persistent HTTP, base page + 4 objects, 4 parallel connections, RTT = 50 ms, transmission negligible. Response time?","HTTP non-persistent, דף בסיס + 4 אובייקטים, 4 חיבורים מקבילים, ‏RTT = 50 ms, שידור זניח. זמן תגובה?"],"o":[["100 ms","100 ms"],["200 ms","200 ms"],["500 ms","500 ms"],["250 ms","250 ms"]],"a":1,"e":["2 RTT for the base page + 2 RTT for the 4 objects in parallel = 4 × 50 = 200 ms.","2 RTT לדף הבסיס + 2 RTT ל-4 האובייקטים במקביל = 4 × 50 = 200 ms."]}],"00":[{"q":["An Ethernet frame carries EtherType 0x0806. What is inside?","Frame של Ethernet נושא EtherType 0x0806. מה יש בפנים?"],"o":[["IPv4","IPv4"],["ARP","ARP"],["IPv6","IPv6"],["VLAN tag","VLAN tag"]],"a":1,"e":["0x0800 = IPv4, 0x0806 = ARP, 0x86DD = IPv6, 0x8100 = 802.1Q tag.","0x0800 = IPv4, ‏0x0806 = ARP, ‏0x86DD = IPv6, ‏0x8100 = תג 802.1Q."]},{"q":["Which IPv4 field does every router decrement, and why?","איזה שדה ב-IPv4 כל נתב מוריד, ולמה?"],"o":[["Identification, to number fragments","Identification, למספור fragments"],["TTL, so packets caught in a loop eventually die","TTL, כדי שחבילות שנתקעו בלולאה ימותו בסוף"],["Protocol, to change transport","Protocol, כדי להחליף תעבורה"],["Total Length","Total Length"]],"a":1,"e":["TTL is decremented at each hop; at 0 the packet is dropped and ICMP Time Exceeded is returned (what traceroute uses). The header checksum is recomputed because TTL changed.","ה-TTL יורד בכל קפיצה; ב-0 החבילה נזרקת ומוחזר ICMP Time Exceeded (מה ש-traceroute מנצל). ה-checksum של ה-header מחושב מחדש כי ה-TTL השתנה."]},{"q":["A TCP segment has flags SYN and ACK set. Which step is it?","ל-segment של TCP דלוקים SYN ו-ACK. איזה שלב זה?"],"o":[["First step of the handshake","השלב הראשון בלחיצת היד"],["Second step: the server's reply","השלב השני: התשובה של השרת"],["Connection teardown","סגירת החיבור"],["A reset","איפוס"]],"a":1,"e":["SYN → SYN/ACK → ACK. A port scanner reading SYN/ACK knows the port is open.","SYN ← SYN/ACK ← ACK. סורק פורטים שרואה SYN/ACK יודע שהפורט פתוח."]},{"q":["A DHCP Discover is sent with which source and destination IP?","DHCP Discover נשלח עם איזה IP מקור ויעד?"],"o":[["192.168.1.10 → 192.168.1.1","192.168.1.10 → 192.168.1.1"],["0.0.0.0 → 255.255.255.255","0.0.0.0 → 255.255.255.255"],["127.0.0.1 → 0.0.0.0","127.0.0.1 → 0.0.0.0"],["255.255.255.255 → 0.0.0.0","255.255.255.255 → 0.0.0.0"]],"a":1,"e":["The client has no address yet, so it uses 0.0.0.0 and broadcasts to 255.255.255.255 over UDP 68 → 67. That broadcast is also why a rogue DHCP server can answer.","ללקוח עוד אין כתובת, ולכן הוא משתמש ב-0.0.0.0 ומשדר ל-255.255.255.255 מעל UDP ‏68 ← 67. ה-broadcast הזה גם הסיבה ששרת DHCP זדוני יכול לענות."]},{"q":["In a DNS response, which field must match the query for the resolver to accept it?","בתשובת DNS, איזה שדה חייב להתאים לשאילתה כדי שה-resolver יקבל אותה?"],"o":[["TTL","TTL"],["The 16-bit Transaction ID (plus the source port and question)","ה-Transaction ID של 16 ביט (וגם פורט המקור והשאלה)"],["The answer count","מספר התשובות"],["The MX record","רשומת MX"]],"a":1,"e":["An off-path attacker must guess the ID (and the randomized port) to poison the cache: the basis of the Kaminsky attack in chapter 04.","תוקף שלא בנתיב חייב לנחש את ה-ID (ואת הפורט האקראי) כדי להרעיל את ה-cache: הבסיס של תקיפת Kaminsky בפרק 04."]},{"q":["ICMP type 3 code 3 means:","ICMP type 3 code 3 פירושו:"],"o":[["Echo reply","Echo reply"],["Destination port unreachable","פורט היעד לא נגיש"],["TTL exceeded","TTL פג"],["Redirect","Redirect"]],"a":1,"e":["Type 3 = destination unreachable; code 3 = port. A UDP scan reads a closed port from this message.","Type 3 = יעד לא נגיש; code 3 = פורט. סריקת UDP מזהה פורט סגור מההודעה הזו."]}],"01":[{"q":["The C in the CIA triad stands for:","ה-C במשולש CIA הוא:"],"o":[["Control","Control"],["Confidentiality","Confidentiality (סודיות)"],["Certification","Certification"],["Compression","Compression"]],"a":1,"e":["Confidentiality, Integrity, Availability. A DoS attack hits availability; tampering hits integrity; sniffing hits confidentiality.","סודיות, שלמות, זמינות. ‏DoS פוגע בזמינות; שינוי מידע פוגע בשלמות; האזנה פוגעת בסודיות."]},{"q":["\"Protection = Prevention + (Detection + Response)\" means:","\"Protection = Prevention + (Detection + Response)\" פירושו:"],"o":[["Prevention alone is enough","מניעה לבדה מספיקה"],["Prevention will eventually fail, so detection and response time matter","המניעה תיכשל בסוף, ולכן זמן הזיהוי והתגובה חשובים"],["Detection is optional","זיהוי הוא אופציונלי"],["Only response matters","רק התגובה חשובה"]],"a":1,"e":["Every barrier buys time; the defense works if detection + response is faster than the time the attacker needs to get through.","כל מחסום קונה זמן; ההגנה עובדת אם זיהוי + תגובה מהירים יותר מהזמן שהתוקף צריך כדי לעבור."]},{"q":["MOM, what an attacker needs, stands for:","MOM, מה שתוקף צריך, הוא:"],"o":[["Method, Opportunity, Motive","Method, ‏Opportunity, ‏Motive"],["Malware, Operator, Money","Malware, ‏Operator, ‏Money"],["Man, On, Middle","Man, ‏On, ‏Middle"],["Monitor, Observe, Modify","Monitor, ‏Observe, ‏Modify"]],"a":0,"e":["Remove any one of the three and the attack fails; defenses usually target opportunity.","מסירים אחד מהשלושה וההתקפה נכשלת; הגנות בדרך כלל מכוונות להזדמנות."]},{"q":["A password plus a code from a phone app is an example of:","סיסמה ועוד קוד מאפליקציה בטלפון הם דוגמה ל:"],"o":[["Two factors: something you know + something you have","שני גורמים: משהו שאתה יודע + משהו שיש לך"],["One factor used twice","גורם אחד פעמיים"],["Biometrics","ביומטריה"],["Least privilege","הרשאה מינימלית"]],"a":0,"e":["The three factors: know (password), have (token, phone), are (biometric). Two passwords are still one factor.","שלושת הגורמים: יודע (סיסמה), יש לו (טוקן, טלפון), הוא (ביומטרי). שתי סיסמאות הן עדיין גורם אחד."]},{"q":["Why does ap3.0 (send IP + password in the clear) fail?","למה ap3.0 (שליחת IP + סיסמה בגלוי) נכשל?"],"o":[["IP addresses are long","כתובות IP ארוכות"],["A sniffer records the packet and replays it later (playback attack)","מאזין מקליט את החבילה ומשדר אותה שוב מאוחר יותר (playback)"],["Passwords are always weak","סיסמאות תמיד חלשות"],["It uses UDP","הוא משתמש ב-UDP"]],"a":1,"e":["Even an encrypted password can be replayed (ap3.1). A nonce (ap4.0) proves liveness, and public keys (ap5.0) remove the shared secret, but open the door to MITM.","גם סיסמה מוצפנת אפשר לשדר שוב (ap3.1). ‏Nonce ‏(ap4.0) מוכיח שהצד השני חי, ומפתחות ציבוריים (ap5.0) מבטלים את הסוד המשותף, אבל פותחים פתח ל-MITM."]},{"q":["\"Defense in depth\" means:","\"Defense in depth\" פירושו:"],"o":[["One very strong firewall","firewall אחד חזק מאוד"],["Several independent layers, so one failure does not expose everything","כמה שכבות עצמאיות, כך שכשל אחד לא חושף הכל"],["Encrypting twice","להצפין פעמיים"],["Hiding the network","להסתיר את הרשת"]],"a":1,"e":["Combined with diversity (different vendors/mechanisms), one vulnerability does not break all layers.","בשילוב עם גיוון (יצרנים/מנגנונים שונים), פגיעות אחת לא שוברת את כל השכבות."]}],"02":[{"q":["Which reconnaissance is passive?","איזה סיור הוא פסיבי?"],"o":[["A port scan of the target","סריקת פורטים של היעד"],["Reading public DNS, whois and social media without touching the target's systems","קריאת DNS ציבורי, whois ורשתות חברתיות בלי לגעת במערכות של היעד"],["Sending phishing mail","שליחת phishing"],["Ping sweep","Ping sweep"]],"a":1,"e":["Passive recon leaves no trace on the target; active recon (scanning) can be logged and detected.","סיור פסיבי לא משאיר עקבות אצל היעד; סיור אקטיבי (סריקה) יכול להירשם ולהתגלות."]},{"q":["A misconfigured DNS server answers an AXFR request from anyone. What leaks?","שרת DNS עם הגדרה שגויה עונה לבקשת AXFR מכל אחד. מה דולף?"],"o":[["Passwords","סיסמאות"],["The whole zone: every hostname and IP in the domain","כל ה-zone: כל שם מחשב וכל IP בדומיין"],["Nothing","כלום"],["The TLS key","מפתח ה-TLS"]],"a":1,"e":["Zone transfers should only be allowed to secondary servers. A full zone is a map of the organization.","zone transfer צריך להיות מותר רק לשרתים משניים. ‏Zone מלא הוא מפה של הארגון."]},{"q":["Which DNS record reveals an organization's mail servers?","איזו רשומת DNS חושפת את שרתי הדואר של ארגון?"],"o":[["A","A"],["MX","MX"],["PTR","PTR"],["TXT","TXT"]],"a":1,"e":["MX. TXT often reveals SPF (which services may send mail for the domain), PTR maps IPs back to names.","MX. ‏TXT חושף לעתים קרובות SPF (אילו שירותים רשאים לשלוח מייל בשם הדומיין), ‏PTR ממפה IP חזרה לשם."]},{"q":["Social engineering targets:","הנדסה חברתית מכוונת ל:"],"o":[["The firewall","ה-firewall"],["People: trust, urgency, authority","אנשים: אמון, דחיפות, סמכות"],["The routing table","טבלת הניתוב"],["Encryption keys directly","ישירות למפתחות הצפנה"]],"a":1,"e":["The cheapest path is often a person. Defenses: training, verification procedures, least privilege.","הדרך הזולה ביותר היא לעתים קרובות אדם. הגנות: הדרכה, נהלי אימות, הרשאה מינימלית."]},{"q":["What did Stuxnet's authors need to learn by reconnaissance?","מה מפתחי Stuxnet היו צריכים ללמוד בסיור?"],"o":[["Only the target's IP","רק את ה-IP של היעד"],["The exact PLC models, configuration and how files reached the air-gapped network","דגמי ה-PLC המדויקים, התצורה ואיך קבצים מגיעים לרשת המנותקת"],["The Wi-Fi password","סיסמת ה-Wi-Fi"],["Nothing","כלום"]],"a":1,"e":["An attack on an isolated industrial network requires deep knowledge of the target environment, gathered long before the attack.","תקיפה על רשת תעשייתית מבודדת דורשת ידע עמוק על סביבת היעד, שנאסף הרבה לפני התקיפה."]},{"q":["In an attack tree, the root is:","בעץ תקיפה, השורש הוא:"],"o":[["The attacker's first step","הצעד הראשון של התוקף"],["The attacker's goal; children are alternative (OR) or required (AND) ways to reach it","המטרה של התוקף; הילדים הם דרכים חלופיות (OR) או נדרשות (AND) להשיג אותה"],["The firewall","ה-firewall"],["A random leaf","עלה אקראי"]],"a":1,"e":["Costs or probabilities on leaves show the cheapest path, which is where defense effort should go.","עלויות או הסתברויות על העלים מראות את המסלול הזול ביותר, ושם צריך להשקיע בהגנה."]}],"03":[{"q":["In a SYN scan, the target answers RST/ACK. The port is:","בסריקת SYN, היעד עונה RST/ACK. הפורט:"],"o":[["Open","פתוח"],["Closed","סגור"],["Filtered","מסונן"],["Open|filtered","Open|filtered"]],"a":1,"e":["SYN/ACK = open (the scanner sends RST instead of completing), RST = closed, no reply or ICMP unreachable = filtered.","SYN/ACK = פתוח (הסורק שולח RST במקום להשלים), ‏RST = סגור, אין תשובה או ICMP unreachable = מסונן."]},{"q":["Why is a SYN scan called \"half-open\"?","למה סריקת SYN נקראת \"half-open\"?"],"o":[["It scans half the ports","היא סורקת חצי מהפורטים"],["It never completes the 3-way handshake, so many applications never log a connection","היא אף פעם לא משלימה את לחיצת היד, ולכן הרבה אפליקציות לא רושמות חיבור"],["It uses UDP","היא משתמשת ב-UDP"],["It needs half the packets of ping","היא צריכה חצי מהחבילות של ping"]],"a":1,"e":["A connect scan (-sT) completes the handshake through the OS and is logged by the service; -sS needs raw sockets (root).","סריקת connect ‏(-sT) משלימה את לחיצת היד דרך מערכת ההפעלה ונרשמת בשירות; ‏-sS צריכה raw sockets ‏(root)."]},{"q":["A Xmas scan sets which flags, and what does a closed port reply (RFC 793)?","סריקת Xmas מדליקה אילו דגלים, ומה פורט סגור עונה (RFC 793)?"],"o":[["SYN; SYN/ACK","SYN; ‏SYN/ACK"],["FIN, PSH, URG; RST","FIN, ‏PSH, ‏URG; ‏RST"],["ACK; nothing","ACK; כלום"],["RST; RST","RST; ‏RST"]],"a":1,"e":["Open ports stay silent, closed ports send RST. Windows sends RST either way, so the scan does not work against it.","פורטים פתוחים שותקים, סגורים שולחים RST. ‏Windows שולח RST בכל מקרה, ולכן הסריקה לא עובדת מולו."]},{"q":["An idle (zombie) scan infers port state from:","סריקת idle ‏(zombie) מסיקה את מצב הפורט מ:"],"o":[["The zombie's TTL","ה-TTL של ה-zombie"],["Increments of the zombie's IP ID field","העליות בשדה ה-IP ID של ה-zombie"],["The target's banner","ה-banner של היעד"],["DNS replies","תשובות DNS"]],"a":1,"e":["A predictable, global IP ID: if it jumped by 2 the zombie sent an RST to the target's SYN/ACK, so the port is open. The target never sees the scanner's address.","IP ID צפוי וגלובלי: אם הוא קפץ ב-2, ה-zombie שלח RST ל-SYN/ACK של היעד, ולכן הפורט פתוח. היעד אף פעם לא רואה את הכתובת של הסורק."]},{"q":["A UDP scan gets no reply from a port. Nmap reports:","סריקת UDP לא מקבלת תשובה מפורט. ‏Nmap מדווח:"],"o":[["open","open"],["closed","closed"],["open|filtered","open|filtered"],["unfiltered","unfiltered"]],"a":2,"e":["UDP has no handshake: silence can mean an open service that ignored the probe or a firewall that dropped it. ICMP port unreachable = closed.","ל-UDP אין לחיצת יד: שקט יכול להיות שירות פתוח שהתעלם או firewall שזרק. ‏ICMP port unreachable = סגור."]},{"q":["What does an ACK scan reveal?","מה סריקת ACK חושפת?"],"o":[["Open ports","פורטים פתוחים"],["Whether a firewall is stateful / which ports are filtered, not open vs closed","האם ה-firewall הוא stateful / אילו פורטים מסוננים, לא פתוח מול סגור"],["The OS version","גרסת מערכת ההפעלה"],["DNS names","שמות DNS"]],"a":1,"e":["A stray ACK gets an RST from any reachable host (unfiltered); no reply means a filter dropped it.","ACK תועה מקבל RST מכל מחשב נגיש (unfiltered); אין תשובה פירושו שמסנן זרק אותו."]}],"04":[{"q":["Why does a switch (unlike a hub) limit what a sniffer sees?","למה switch (בניגוד ל-hub) מגביל את מה שמאזין רואה?"],"o":[["It encrypts frames","הוא מצפין frames"],["It forwards unicast frames only to the port where the destination MAC was learned","הוא מעביר frames של unicast רק לפורט שבו נלמד ה-MAC של היעד"],["It blocks ARP","הוא חוסם ARP"],["It changes IP addresses","הוא משנה כתובות IP"]],"a":1,"e":["A sniffer on a switch sees only its own traffic plus broadcasts, unless it floods the CAM table or poisons ARP.","מאזין על switch רואה רק את התעבורה שלו ועוד broadcasts, אלא אם הוא מציף את טבלת ה-CAM או מרעיל ARP."]},{"q":["In ARP poisoning, the attacker sends:","ב-ARP poisoning, התוקף שולח:"],"o":[["Forged ARP replies mapping the gateway's IP to the attacker's MAC","תשובות ARP מזויפות שממפות את ה-IP של ה-gateway ל-MAC של התוקף"],["DNS queries","שאילתות DNS"],["TCP SYNs","TCP SYNs"],["ICMP redirects only","רק ICMP redirects"]],"a":0,"e":["ARP has no authentication and most hosts accept unsolicited replies. Defenses: static entries, Dynamic ARP Inspection, arpwatch.","ל-ARP אין אימות ורוב המחשבים מקבלים תשובות שלא ביקשו. הגנות: רשומות סטטיות, ‏Dynamic ARP Inspection, ‏arpwatch."]},{"q":["A blind (off-path) attacker wants to inject into a TCP connection. What must it guess?","תוקף עיוור (מחוץ לנתיב) רוצה להזריק לחיבור TCP. מה הוא חייב לנחש?"],"o":[["Only the destination port","רק את פורט היעד"],["The 4-tuple and a sequence number inside the receiver's window","את ה-4-tuple ומספר רצף בתוך החלון של המקבל"],["The MAC address","את כתובת ה-MAC"],["Nothing","כלום"]],"a":1,"e":["Random ISNs and ephemeral ports make this hard; a larger window makes a RST attack easier.","ISNs ופורטים אקראיים מקשים על זה; חלון גדול יותר מקל על תקיפת RST."]},{"q":["A rogue DHCP server can:","שרת DHCP זדוני יכול:"],"o":[["Hand out itself as the default gateway or DNS server, becoming a man in the middle","לחלק את עצמו כ-default gateway או שרת DNS, ולהפוך לאדם בתווך"],["Change MAC addresses","לשנות כתובות MAC"],["Break TLS","לשבור TLS"],["Nothing, DHCP is authenticated","כלום, DHCP מאומת"]],"a":0,"e":["DHCP starvation first exhausts the real server's pool; DHCP snooping on switches (trusted ports) is the defense.","DHCP starvation קודם מרוקן את המאגר של השרת האמיתי; DHCP snooping ב-switches (פורטים מהימנים) הוא ההגנה."]},{"q":["What made the Kaminsky attack much stronger than classic DNS poisoning?","מה הפך את תקיפת Kaminsky לחזקה הרבה יותר מהרעלת DNS קלאסית?"],"o":[["It broke DNSSEC","היא שברה DNSSEC"],["Querying random non-existent subdomains gives unlimited attempts, and the forged reply injects a fake NS for the whole domain","שאילתות לתתי-דומיינים אקראיים שלא קיימים נותנות ניסיונות בלי הגבלה, והתשובה המזויפת מזריקה NS מזויף לכל הדומיין"],["It used TCP","היא השתמשה ב-TCP"],["It needed physical access","היא דרשה גישה פיזית"]],"a":1,"e":["No waiting for the cached TTL to expire. Fix: source port randomization (16 more bits to guess), and DNSSEC.","אין צורך לחכות שה-TTL ב-cache יפוג. התיקון: פורט מקור אקראי (עוד 16 ביט לנחש), ו-DNSSEC."]},{"q":["MAC flooding attacks the switch by:","MAC flooding תוקף את ה-switch ע\"י:"],"o":[["Filling its CAM table with fake source MACs so it floods frames like a hub","מילוי טבלת ה-CAM שלו ב-MACs מזויפים כך שהוא מציף frames כמו hub"],["Changing its IP","שינוי ה-IP שלו"],["Sending large frames","שליחת frames גדולים"],["Cutting the cable","חיתוך הכבל"]],"a":0,"e":["Port security (limit MACs per port) stops it.","Port security (הגבלת MACs לכל פורט) עוצר את זה."]}],"05":[{"q":["What resource does a SYN flood exhaust?","איזה משאב SYN flood מרוקן?"],"o":[["Bandwidth only","רק רוחב פס"],["The server's backlog of half-open connections","ה-backlog של השרת של חיבורים חצי-פתוחים"],["DNS cache","cache של DNS"],["CPU of routers","מעבד הנתבים"]],"a":1,"e":["Spoofed SYNs never complete the handshake; each one holds a backlog slot until timeout, and legitimate SYNs are dropped.","SYNs מזויפים אף פעם לא משלימים את לחיצת היד; כל אחד תופס מקום ב-backlog עד timeout, ו-SYNs לגיטימיים נזרקים."]},{"q":["SYN cookies defend by:","SYN cookies מגינים ע\"י:"],"o":[["Dropping all SYNs","זריקת כל ה-SYNs"],["Encoding the connection state in the server's ISN, so no memory is kept until the final ACK","קידוד מצב החיבור ב-ISN של השרת, כך שלא נשמר זיכרון עד ה-ACK האחרון"],["Encrypting the SYN","הצפנת ה-SYN"],["Using UDP","שימוש ב-UDP"]],"a":1,"e":["ISN = hash(4-tuple, secret, time) + MSS bits. A valid ACK (ack − 1) proves the client got the SYN/ACK.","ISN = hash(4-tuple, secret, time) + ביטי MSS. ‏ACK תקין (ack − 1) מוכיח שהלקוח קיבל את ה-SYN/ACK."]},{"q":["In a Smurf attack, the attacker sends ICMP echo requests:","בתקיפת Smurf, התוקף שולח ICMP echo requests:"],"o":[["To the victim directly","ישירות לקורבן"],["To a broadcast address with the victim's spoofed source IP","לכתובת broadcast עם ה-IP של הקורבן כמקור מזויף"],["To DNS servers","לשרתי DNS"],["With TTL 0","עם TTL 0"]],"a":1,"e":["Every host on that network replies to the victim (amplification). Fix: routers don't forward directed broadcasts.","כל מחשב ברשת הזו עונה לקורבן (הגברה). התיקון: נתבים לא מעבירים directed broadcasts."]},{"q":["A DNS amplification attack works because:","תקיפת DNS amplification עובדת כי:"],"o":[["DNS uses TCP","DNS משתמש ב-TCP"],["A small spoofed UDP query produces a much larger response sent to the victim","שאילתת UDP קטנה ומזויפת מייצרת תשובה גדולה הרבה יותר שנשלחת לקורבן"],["DNS encrypts","DNS מצפין"],["Resolvers are slow","resolvers איטיים"]],"a":1,"e":["Amplification factor = response size / request size. Defenses: no open resolvers, rate limiting, BCP 38 ingress filtering against spoofing.","מקדם הגברה = גודל התשובה / גודל הבקשה. הגנות: בלי resolvers פתוחים, הגבלת קצב, סינון BCP 38 נגד זיוף."]},{"q":["Teardrop crashed systems by sending:","Teardrop הפיל מערכות ע\"י שליחת:"],"o":[["Overlapping IP fragments with bad offsets","fragments של IP חופפים עם offsets שגויים"],["Large ICMP packets","חבילות ICMP גדולות"],["SYN packets","חבילות SYN"],["DNS queries","שאילתות DNS"]],"a":0,"e":["The reassembly code computed a negative length. Ping of Death was an oversized reassembled ICMP packet (&gt; 65,535 bytes).","קוד ההרכבה חישב אורך שלילי. ‏Ping of Death הייתה חבילת ICMP מורכבת גדולה מדי (&gt; 65,535 בתים)."]},{"q":["A \"low and slow\" attack such as Slowloris:","תקיפת \"low and slow\" כמו Slowloris:"],"o":[["Floods with gigabits of traffic","מציפה בג'יגה-ביטים"],["Holds many HTTP connections open by sending headers very slowly, exhausting the server's connection pool","מחזיקה הרבה חיבורי HTTP פתוחים ע\"י שליחת headers לאט מאוד, וממצה את מאגר החיבורים של השרת"],["Spoofs IPs","מזייפת IPs"],["Uses ICMP","משתמשת ב-ICMP"]],"a":1,"e":["Little bandwidth, hard to tell from slow clients. Defenses: timeouts, per-IP limits, reverse proxies.","מעט רוחב פס, קשה להבדיל מלקוחות איטיים. הגנות: timeouts, הגבלה לכל IP, ‏reverse proxies."]}],"06":[{"q":["Kerckhoffs's principle says:","העיקרון של Kerckhoffs אומר:"],"o":[["Keep the algorithm secret","לשמור את האלגוריתם בסוד"],["Security must depend only on the secrecy of the key, not of the algorithm","האבטחה חייבת להיות תלויה רק בסודיות המפתח, לא של האלגוריתם"],["Use long passwords","להשתמש בסיסמאות ארוכות"],["Never reuse keys","לא לחזור על מפתחות"]],"a":1,"e":["Public, peer-reviewed algorithms (AES) are safer than secret ones.","אלגוריתמים ציבוריים שנבדקו (AES) בטוחים יותר מסודיים."]},{"q":["Why is ECB mode insecure for images?","למה מצב ECB לא בטוח לתמונות?"],"o":[["It is slow","הוא איטי"],["Identical plaintext blocks give identical ciphertext blocks, so patterns remain visible","בלוקים זהים של טקסט גלוי נותנים בלוקים זהים של מוצפן, ולכן תבניות נשארות גלויות"],["It needs a long key","הוא צריך מפתח ארוך"],["It is a stream cipher","הוא צופן זרם"]],"a":1,"e":["CBC XORs each block with the previous ciphertext (and an IV for the first), hiding repetition.","CBC עושה XOR לכל בלוק עם המוצפן הקודם (ועם IV לראשון), ומסתיר חזרות."]},{"q":["A One-Time Pad is perfectly secure if the key is:","One-Time Pad בטוח לחלוטין אם המפתח:"],"o":[["Short and reused","קצר וחוזר"],["Truly random, as long as the message, and never reused","אקראי באמת, באורך ההודעה, ולא בשימוש חוזר"],["A password","סיסמה"],["Public","ציבורי"]],"a":1,"e":["Reusing a pad: C1 ⊕ C2 = P1 ⊕ P2, which leaks the plaintexts.","שימוש חוזר: ‏C1 ⊕ C2 = P1 ⊕ P2, וזה מדליף את הטקסטים."]},{"q":["Diffie-Hellman with p = 23, g = 5, a = 6, b = 15. The shared key is:","Diffie-Hellman עם p = 23, ‏g = 5, ‏a = 6, ‏b = 15. המפתח המשותף:"],"o":[["2","2"],["8","8"],["19","19"],["6","6"]],"a":0,"e":["A = 5<sup>6<\/sup> mod 23 = 8, B = 5<sup>15<\/sup> mod 23 = 19. K = B<sup>a<\/sup> = 19<sup>6<\/sup> mod 23 = 2 = A<sup>b<\/sup> = 8<sup>15<\/sup> mod 23.","A = 5<sup>6<\/sup> mod 23 = 8, ‏B = 5<sup>15<\/sup> mod 23 = 19. ‏K = B<sup>a<\/sup> = 19<sup>6<\/sup> mod 23 = 2 = A<sup>b<\/sup> = 8<sup>15<\/sup> mod 23."]},{"q":["Why was 3DES built as Encrypt-Decrypt-Encrypt instead of double DES?","למה 3DES נבנה כ-Encrypt-Decrypt-Encrypt ולא כ-DES כפול?"],"o":[["Double DES is vulnerable to meet-in-the-middle, giving only ~57 bits of security","DES כפול פגיע ל-meet-in-the-middle, ונותן רק ~57 ביט אבטחה"],["It is faster","זה מהיר יותר"],["DES has no decryption","ל-DES אין פענוח"],["For compression","לדחיסה"]],"a":0,"e":["EDE with K1 = K2 also stays backward compatible with single DES.","EDE עם K1 = K2 גם נשאר תואם לאחור ל-DES רגיל."]},{"q":["A Feistel network's key property is:","התכונה המרכזית של רשת Feistel:"],"o":[["The round function must be invertible","פונקציית הסיבוב חייבת להיות הפיכה"],["Decryption is the same structure with the round keys in reverse order, whatever the round function is","הפענוח הוא אותו מבנה עם מפתחות הסיבוב בסדר הפוך, בלי קשר לפונקציית הסיבוב"],["It needs no key","היא לא צריכה מפתח"],["It is a stream cipher","היא צופן זרם"]],"a":1,"e":["L<sub>i<\/sub> = R<sub>i−1<\/sub>, R<sub>i<\/sub> = L<sub>i−1<\/sub> ⊕ F(R<sub>i−1<\/sub>, K<sub>i<\/sub>). DES is a 16-round Feistel; AES is not a Feistel (substitution-permutation network).","L<sub>i<\/sub> = R<sub>i−1<\/sub>, ‏R<sub>i<\/sub> = L<sub>i−1<\/sub> ⊕ F(R<sub>i−1<\/sub>, K<sub>i<\/sub>). ‏DES הוא Feistel של 16 סיבובים; AES אינו Feistel ‏(SPN)."]}],"07":[{"q":["RSA with p = 5, q = 11, e = 3. What is d?","RSA עם p = 5, ‏q = 11, ‏e = 3. מה d?"],"o":[["7","7"],["27","27"],["13","13"],["33","33"]],"a":1,"e":["n = 55, φ = 4 × 10 = 40. d = e<sup>−1<\/sup> mod 40: 3 × 27 = 81 = 2 × 40 + 1 → d = 27.","n = 55, ‏φ = 4 × 10 = 40. ‏d = e<sup>−1<\/sup> mod 40: ‏3 × 27 = 81 = 2 × 40 + 1 ← d = 27."]},{"q":["A digital signature provides which property a MAC does not?","חתימה דיגיטלית מספקת איזו תכונה ש-MAC לא?"],"o":[["Integrity","שלמות"],["Non-repudiation: only the private-key holder could have signed","אי-התכחשות: רק מחזיק המפתח הפרטי יכול היה לחתום"],["Confidentiality","סודיות"],["Speed","מהירות"]],"a":1,"e":["A MAC uses a shared key, so either party could have produced it.","MAC משתמש במפתח משותף, ולכן כל אחד מהצדדים יכול היה לייצר אותו."]},{"q":["By the birthday paradox, how much work finds a collision in a 128-bit hash?","לפי פרדוקס יום ההולדת, כמה עבודה דרושה כדי למצוא התנגשות ב-hash של 128 ביט?"],"o":[["2<sup>128<\/sup>","2<sup>128<\/sup>"],["2<sup>64<\/sup>","2<sup>64<\/sup>"],["2<sup>32<\/sup>","2<sup>32<\/sup>"],["128","128"]],"a":1,"e":["About 2<sup>n/2<\/sup> tries. That is why 256-bit hashes are used for 128-bit security.","בערך 2<sup>n/2<\/sup> ניסיונות. לכן משתמשים ב-hash של 256 ביט לאבטחה של 128 ביט."]},{"q":["What does a CA certificate bind together?","מה תעודה של CA קושרת יחד?"],"o":[["A name (subject) and a public key, signed by the CA's private key","שם (subject) ומפתח ציבורי, חתומים במפתח הפרטי של ה-CA"],["A password and a username","סיסמה ושם משתמש"],["An IP and a MAC","IP ו-MAC"],["Two private keys","שני מפתחות פרטיים"]],"a":0,"e":["The browser verifies the signature with the CA's public key (pre-installed root), which defeats the MITM against plain DH or ap5.0.","הדפדפן מאמת את החתימה עם המפתח הציבורי של ה-CA (root מותקן מראש), וזה מנטרל את ה-MITM נגד DH רגיל או ap5.0."]},{"q":["In TLS, public-key crypto is used for:","ב-TLS, קריפטוגרפיה של מפתח ציבורי משמשת ל:"],"o":[["Encrypting all the data","הצפנת כל המידע"],["Authenticating the server and establishing a shared session key; the bulk data uses symmetric encryption","אימות השרת והקמת מפתח session משותף; המידע עצמו מוצפן סימטרית"],["Compression","דחיסה"],["Nothing","כלום"]],"a":1,"e":["Public-key operations are ~1000× slower; a hybrid scheme gets the best of both.","פעולות מפתח ציבורי איטיות בערך פי 1000; שיטה היברידית מקבלת את הטוב משני העולמות."]},{"q":["Hash properties: finding any two messages with the same hash is resistance to:","תכונות hash: למצוא שתי הודעות כלשהן עם אותו hash זה עמידות ל:"],"o":[["Preimage","Preimage"],["Second preimage","Second preimage"],["Collision","Collision (התנגשות)"],["Brute force on the key","Brute force על המפתח"]],"a":2,"e":["Preimage: given h find m. Second preimage: given m find m' ≠ m with the same hash. Collision: find any pair; the easiest (birthday).","Preimage: בהינתן h למצוא m. ‏Second preimage: בהינתן m למצוא m' ≠ m עם אותו hash. ‏Collision: למצוא זוג כלשהו; הקלה ביותר (יום הולדת)."]}],"08":[{"q":["Why can anyone forge the \"From:\" of an email with plain SMTP?","למה כל אחד יכול לזייף את ה-\"From:\" של מייל ב-SMTP רגיל?"],"o":[["SMTP encrypts it","SMTP מצפין אותו"],["SMTP never authenticated the sender: MAIL FROM and From: are just text the client types","SMTP אף פעם לא אימת את השולח: ‏MAIL FROM ו-From: הם רק טקסט שהלקוח מקליד"],["Because of DNS","בגלל DNS"],["It cannot be forged","אי אפשר לזייף"]],"a":1,"e":["Today SPF, DKIM and DMARC let receivers check the sending domain.","היום SPF, ‏DKIM ו-DMARC מאפשרים למקבל לבדוק את הדומיין השולח."]},{"q":["In PGP, a message is encrypted with:","ב-PGP, הודעה מוצפנת עם:"],"o":[["The recipient's public key directly","ישירות המפתח הציבורי של הנמען"],["A random session key (symmetric), which is itself encrypted with the recipient's public key","מפתח session אקראי (סימטרי), שבעצמו מוצפן במפתח הציבורי של הנמען"],["The sender's private key","המפתח הפרטי של השולח"],["A password","סיסמה"]],"a":1,"e":["Sign (hash + sender's private key) → compress → encrypt with session key → encrypt session key with recipient's public key → Radix-64.","חתימה (hash + המפתח הפרטי של השולח) ← דחיסה ← הצפנה במפתח session ← הצפנת מפתח ה-session במפתח הציבורי של הנמען ← Radix-64."]},{"q":["Why does PGP compress after signing but before encrypting?","למה PGP דוחס אחרי החתימה אבל לפני ההצפנה?"],"o":[["Signing the uncompressed text keeps the signature independent of the compression version; compressing before encrypting removes redundancy and shrinks the data","חתימה על הטקסט הלא דחוס שומרת את החתימה בלתי תלויה בגרסת הדחיסה; דחיסה לפני הצפנה מסירה יתירות ומקטינה את המידע"],["It is random","זה אקראי"],["Encrypted data compresses better","מידע מוצפן נדחס טוב יותר"],["Required by SMTP","SMTP מחייב"]],"a":0,"e":["Encrypted data looks random and does not compress, so compression must come first.","מידע מוצפן נראה אקראי ולא נדחס, ולכן הדחיסה חייבת לבוא קודם."]},{"q":["Radix-64 encoding increases size by about:","קידוד Radix-64 מגדיל את הגודל בערך ב:"],"o":[["10%","10%"],["33%","33%"],["50%","50%"],["100%","100%"]],"a":1,"e":["Every 3 bytes become 4 printable characters, so binary survives 7-bit SMTP.","כל 3 בתים הופכים ל-4 תווים מודפסים, כך שמידע בינארי שורד את SMTP של 7 ביט."]},{"q":["PGP's trust model is:","מודל האמון של PGP הוא:"],"o":[["A strict CA hierarchy","היררכיית CA נוקשה"],["A web of trust: users sign each other's keys","Web of trust: משתמשים חותמים על המפתחות זה של זה"],["No trust at all","אין אמון בכלל"],["DNS-based","מבוסס DNS"]],"a":1,"e":["S/MIME uses X.509 certificates from CAs instead.","S/MIME משתמש במקום זה בתעודות X.509 מ-CAs."]},{"q":["DKIM proves:","DKIM מוכיח:"],"o":[["The sender's IP is allowed","שה-IP של השולח מורשה"],["The message was signed by a key published in the sending domain's DNS, and the signed headers/body were not modified","שההודעה נחתמה במפתח שמפורסם ב-DNS של הדומיין השולח, וה-headers/גוף החתומים לא שונו"],["The message is encrypted","שההודעה מוצפנת"],["Nothing","כלום"]],"a":1,"e":["SPF lists allowed sending IPs; DMARC ties them to the visible From: domain and sets a policy.","SPF מפרט IPs מורשים לשליחה; ‏DMARC קושר אותם לדומיין ה-From: הגלוי וקובע מדיניות."]}],"09":[{"q":["A stateless packet filter decides by:","מסנן חבילות stateless מחליט לפי:"],"o":[["The application payload","התוכן של האפליקציה"],["Each packet's header fields alone (IPs, ports, protocol, flags), with no memory of earlier packets","שדות ה-header של כל חבילה בלבד (IPs, פורטים, פרוטוקול, דגלים), בלי זיכרון של חבילות קודמות"],["The user name","שם המשתמש"],["A connection table","טבלת חיבורים"]],"a":1,"e":["That is why it must allow inbound ACK packets to high ports for replies, which an ACK scan can probe.","לכן הוא חייב לאפשר חבילות ACK נכנסות לפורטים גבוהים בשביל תשובות, ואת זה סריקת ACK יכולה לבדוק."]},{"q":["What does a stateful firewall add?","מה firewall מסוג stateful מוסיף?"],"o":[["Encryption","הצפנה"],["A connection table: inbound packets are allowed only if they belong to a connection started from inside","טבלת חיבורים: חבילות נכנסות מותרות רק אם הן שייכות לחיבור שהתחיל מבפנים"],["Antivirus","אנטי-וירוס"],["NAT only","רק NAT"]],"a":1,"e":["It tracks the TCP state machine (and pseudo-state for UDP), so a stray ACK is dropped.","הוא עוקב אחרי מכונת המצבים של TCP (ומצב מדומה ל-UDP), ולכן ACK תועה נזרק."]},{"q":["Rules are checked top to bottom, first match wins. Where should a \"deny all\" rule go?","הכללים נבדקים מלמעלה למטה, ההתאמה הראשונה מנצחת. איפה צריך להיות כלל \"deny all\"?"],"o":[["First","ראשון"],["Last, as the default for anything not explicitly allowed (whitelist)","אחרון, כברירת מחדל לכל מה שלא הותר במפורש (whitelist)"],["In the middle","באמצע"],["It is not needed","לא צריך אותו"]],"a":1,"e":["A deny-all at the top would block everything; specific rules before general ones.","deny-all בראש היה חוסם הכל; כללים ספציפיים לפני כלליים."]},{"q":["A public web server should be placed:","שרת web ציבורי צריך להיות ממוקם:"],"o":[["Inside the internal LAN","בתוך ה-LAN הפנימי"],["In the DMZ, reachable from outside but separated from the internal network","ב-DMZ, נגיש מבחוץ אבל מופרד מהרשת הפנימית"],["Outside any firewall","מחוץ לכל firewall"],["On the firewall itself","על ה-firewall עצמו"]],"a":1,"e":["If the web server is compromised, the attacker still has to pass the inner firewall.","אם שרת ה-web נפרץ, התוקף עדיין צריך לעבור את ה-firewall הפנימי."]},{"q":["Which firewall type can block a specific HTTP command or URL?","איזה סוג firewall יכול לחסום פקודת HTTP או URL מסוימים?"],"o":[["Packet filter","Packet filter"],["Application-level gateway (proxy)","Application-level gateway ‏(proxy)"],["Circuit-level gateway","Circuit-level gateway"],["A hub","Hub"]],"a":1,"e":["It understands the application protocol, at the cost of one proxy per service and more processing.","הוא מבין את פרוטוקול האפליקציה, במחיר של proxy לכל שירות ויותר עיבוד."]},{"q":["iptables: which command drops all inbound traffic except established connections and SSH?","iptables: איזו פקודה זורקת כל תעבורה נכנסת חוץ מחיבורים קיימים ו-SSH?"],"o":[["iptables -P INPUT ACCEPT","iptables -P INPUT ACCEPT"],["iptables -A INPUT -m conntrack --ctstate ESTABLISHED,RELATED -j ACCEPT; iptables -A INPUT -p tcp --dport 22 -j ACCEPT; iptables -P INPUT DROP","iptables -A INPUT -m conntrack --ctstate ESTABLISHED,RELATED -j ACCEPT; iptables -A INPUT -p tcp --dport 22 -j ACCEPT; iptables -P INPUT DROP"],["iptables -F","iptables -F"],["iptables -t nat -L","iptables -t nat -L"]],"a":1,"e":["Allow what you need, then a default DROP policy. -F flushes all rules; -L lists them.","מאשרים את מה שצריך, ואז מדיניות ברירת מחדל DROP. ‏-F מוחק את כל הכללים; ‏-L מציג אותם."]}],"10":[{"q":["Which Wireshark display filter shows only TCP SYN packets without ACK?","איזה display filter ב-Wireshark מציג רק חבילות TCP SYN בלי ACK?"],"o":[["tcp.port == 80","tcp.port == 80"],["tcp.flags.syn == 1 && tcp.flags.ack == 0","tcp.flags.syn == 1 && tcp.flags.ack == 0"],["syn only","syn only"],["ip.proto == 6","ip.proto == 6"]],"a":1,"e":["Display filters use field names (tcp.flags.syn). Capture filters use BPF syntax, like tcpdump: 'tcp[tcpflags] &amp; tcp-syn != 0'.","Display filters משתמשים בשמות שדות (tcp.flags.syn). ‏Capture filters משתמשים בתחביר BPF, כמו tcpdump: 'tcp[tcpflags] &amp; tcp-syn != 0'."]},{"q":["Which dig command asks for a domain's mail servers?","איזו פקודת dig שואלת על שרתי הדואר של דומיין?"],"o":[["dig example.com A","dig example.com A"],["dig example.com MX","dig example.com MX"],["dig -x example.com","dig -x example.com"],["dig example.com AXFR","dig example.com AXFR"]],"a":1,"e":["-x does a reverse (PTR) lookup; AXFR requests a zone transfer (usually refused).","-x עושה חיפוש הפוך (PTR); ‏AXFR מבקש zone transfer (בדרך כלל נדחה)."]},{"q":["nmap -sV adds:","nmap -sV מוסיף:"],"o":[["OS detection","זיהוי מערכת הפעלה"],["Service and version detection on open ports","זיהוי שירות וגרסה בפורטים פתוחים"],["UDP scanning","סריקת UDP"],["Stealth","הסוואה"]],"a":1,"e":["-O = OS fingerprinting, -sU = UDP, -sS = SYN scan, -p = port list, -Pn = skip host discovery.","-O = זיהוי מערכת הפעלה, ‏-sU = UDP, ‏-sS = סריקת SYN, ‏-p = רשימת פורטים, ‏-Pn = בלי גילוי מחשבים."]},{"q":["With hping3, a single SYN to port 80 returns flags=SA. The port is:","עם hping3, ‏SYN אחד לפורט 80 מחזיר flags=SA. הפורט:"],"o":[["Closed","סגור"],["Open","פתוח"],["Filtered","מסונן"],["Unknown","לא ידוע"]],"a":1,"e":["SA = SYN/ACK = open; RA = RST/ACK = closed; nothing = filtered.","SA = SYN/ACK = פתוח; ‏RA = RST/ACK = סגור; כלום = מסונן."]},{"q":["What does \"openssl s_client -connect host:443\" show?","מה \"openssl s_client -connect host:443\" מציג?"],"o":[["The server's certificate chain, the TLS version and the cipher suite","שרשרת התעודות של השרת, גרסת TLS וה-cipher suite"],["Open ports","פורטים פתוחים"],["The DNS records","רשומות DNS"],["The ARP cache","ה-ARP cache"]],"a":0,"e":["Use it to check what chapter 07 describes: subject, issuer, validity and the handshake result.","משתמשים בזה כדי לבדוק את מה שפרק 07 מתאר: subject, ‏issuer, תוקף ותוצאת לחיצת היד."]},{"q":["Before running any active tool (nmap, hping3) you must have:","לפני שמריצים כלי אקטיבי (nmap, ‏hping3) חייבים:"],"o":[["A fast connection","חיבור מהיר"],["Written authorization for the exact targets, or your own isolated lab","הרשאה בכתב ליעדים המדויקים, או מעבדה מבודדת משלך"],["Root on the target","root על היעד"],["Nothing","כלום"]],"a":1,"e":["Scanning systems you do not own or are not authorized to test can be illegal; the course lab uses VMs on a host-only network.","סריקה של מערכות שאינן שלך או שלא קיבלת הרשאה לבדוק עלולה להיות לא חוקית; המעבדה בקורס משתמשת ב-VMs ברשת host-only."]}]};
/* Practice quizzes: per-chapter quiz at the end of each chapter, and a mixed practice page (#quiz).
   Data: window.QUIZ_DATA = { chapterId: [ {q:[en,he], o:[[en,he],...], a:index, e:[en,he]} ] } */
(function () {
  'use strict';
  const D = window.QUIZ_DATA || {};
  const he = () => window.LANG === 'he';
  const tx = (p) => (Array.isArray(p) ? (he() ? p[1] : p[0]) : p);
  const U = {
    en: { h: 'Check yourself', score: 'Score', of: ' / ', reset: 'Reset', correct: 'Correct. ', wrong: 'Not quite. ', q: 'Q', pick: 'Pick an answer to see the explanation.',
      pH1: 'Practice quiz', pEy: 'Exam practice', pLead: 'Random questions from a course or a chapter, with an explanation for every answer. Original questions written for these notes, in the style of the course exams.',
      all: 'Whole course', n: 'Questions', go: 'New set', done: 'Finished: ', perfect: 'Perfect score.', retry: 'Review the explanations of the ones you missed, then try a new set.' },
    he: { h: 'בדקו את עצמכם', score: 'ציון', of: ' / ', reset: 'איפוס', correct: 'נכון. ', wrong: 'לא בדיוק. ', q: 'שאלה ', pick: 'בחרו תשובה כדי לראות הסבר.',
      pH1: 'תרגול למבחן', pEy: 'תרגול', pLead: 'שאלות אקראיות מקורס או מפרק, עם הסבר לכל תשובה. שאלות מקוריות שנכתבו לסיכומים האלה, בסגנון המבחנים של הקורס.',
      all: 'כל הקורס', n: 'שאלות', go: 'סט חדש', done: 'סיימתם: ', perfect: 'ציון מלא.', retry: 'עברו על ההסברים של השאלות שפספסתם, ואז נסו סט חדש.' }
  };
  const u = (k) => U[he() ? 'he' : 'en'][k];
  const esc = (s) => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

  function render(host, items, title, onDone) {
    let right = 0, answered = 0;
    host.innerHTML = '';
    const box = document.createElement('div'); box.className = 'quiz';
    box.innerHTML = '<div class="quiz-h"><h3>' + esc(title) + '</h3><span class="score"></span></div>';
    const sc = box.querySelector('.score');
    const upd = () => { sc.textContent = u('score') + ': ' + right + u('of') + answered + ' (' + items.length + ')'; };
    items.forEach((it, i) => {
      const d = document.createElement('div'); d.className = 'qq';
      d.innerHTML = '<div class="qn">' + u('q') + (i + 1) + (it.ch ? ' · ' + esc(it.ch.toUpperCase()) : '') + '</div><div class="qt">' + tx(it.q) + '</div><div class="opts"></div>';
      const opts = d.querySelector('.opts');
      it.o.forEach((o, k) => {
        const b = document.createElement('button'); b.type = 'button'; b.className = 'opt';
        b.innerHTML = '<b>' + 'ABCDEF'[k] + '</b><span>' + tx(o) + '</span>';
        b.onclick = () => {
          answered++; const ok = k === it.a; if (ok) right++;
          opts.querySelectorAll('.opt').forEach((x, j) => { x.disabled = true; if (j === it.a) x.classList.add('ok'); else if (j === k) x.classList.add('bad'); });
          const ex = document.createElement('div'); ex.className = 'ex'; ex.innerHTML = '<b>' + (ok ? u('correct') : u('wrong')) + '</b>' + tx(it.e);
          d.appendChild(ex); upd();
          if (answered === items.length && onDone) onDone(right, items.length, box);
        };
        opts.appendChild(b);
      });
      box.appendChild(d);
    });
    upd();
    host.appendChild(box);
  }
  function shuffle(a) { a = a.slice(); for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; }
  function finish(r, n, box) {
    const p = document.createElement('p'); p.className = 'ex'; p.style.marginTop = '1rem';
    p.innerHTML = '<b>' + u('done') + r + ' / ' + n + '.</b> ' + (r === n ? u('perfect') : u('retry'));
    box.appendChild(p);
  }

  window.Quiz = {
    count: (ch) => (D[ch] || []).length,
    total: () => Object.values(D).reduce((s, a) => s + a.length, 0),
    mount: (el, ch) => { const list = D[ch]; if (!list || !list.length) { el.remove(); return; } render(el, list, u('h'), finish); },
    page: (w, sel, COURSES, getCh, lab, cT) => {
      w.innerHTML = '<header class="top"><div class="eyebrow">' + u('pEy') + '</div><h1>' + u('pH1') + '</h1><p class="lead">' + u('pLead') + '</p></header>'
        + '<div class="quiz-tools"><select id="qzSel" aria-label="' + esc(u('all')) + '"></select><select id="qzN" aria-label="' + esc(u('n')) + '"><option>10</option><option>20</option><option>40</option></select><button type="button" class="pri" id="qzGo">' + u('go') + '</button></div><div id="qzHost"></div>';
      const s = w.querySelector('#qzSel');
      COURSES.forEach(k => {
        const g = document.createElement('optgroup'); g.label = he() ? k.ht : k.t;
        const all = document.createElement('option'); all.value = k.key; all.textContent = u('all') + ' · ' + (he() ? k.ht : k.t); g.appendChild(all);
        k.subj.forEach(sj => sj.ch.forEach(id => { if (!D[id] || !D[id].length) return; const o = document.createElement('option'); o.value = id; o.textContent = lab(id) + ' · ' + cT(getCh(id)) + ' (' + D[id].length + ')'; g.appendChild(o); }));
        s.appendChild(g);
      });
      if (sel && [...s.options].some(o => o.value === sel)) s.value = sel;
      const go = () => {
        const v = s.value, n = +w.querySelector('#qzN').value;
        const k = COURSES.find(c => c.key === v);
        const ids = k ? k.subj.flatMap(g => g.ch) : [v];
        const pool = ids.flatMap(id => (D[id] || []).map(q => Object.assign({ ch: id }, q)));
        render(w.querySelector('#qzHost'), shuffle(pool).slice(0, n), (k ? (he() ? k.ht : k.t) : lab(v) + ' · ' + cT(getCh(v))), finish);
        try { history.replaceState(null, '', '#quiz-' + v); } catch (e) {}
      };
      w.querySelector('#qzGo').onclick = go; s.onchange = go;
      go();
    }
  };
})();
